// Near-copy / lookalike check for textures (pure, client-safe). Two uses:
//  1. inside the library: no two templates may be near-copies of each other, and no two variants of one template
//     may be colour lookalikes (the test enforces both, so the owner never browses ten copies of one thing);
//  2. against VANILLA textures: `checkNearCopy` compares a texture with reference fingerprints. The reference set is
//     NOT in git (Mojang's art must not be committed or shipped): an operator computes fingerprints on the build host
//     from the server jar with `fingerprint()` and passes them in. With no reference set the check reports
//     "not_run" (honest stub) - it never claims a texture is clean when nothing was compared.
// Colour distance = mean RGB distance over the twelfth of shared cells that differ most.
// Fingerprint = the texture box-sampled to 16x16: an alpha mask plus luminance and mean colour per cell.
import type { Raster } from "../textures/render";

export type Fingerprint = { mask: number[]; lum: number[]; rgb: [number, number, number][] };
const G = 16;

export function fingerprint(img: Raster): Fingerprint {
  const n = img.size, s = n / G, px = img.px;
  const mask: number[] = [], lum: number[] = [], rgb: [number, number, number][] = [];
  for (let gy = 0; gy < G; gy++) for (let gx = 0; gx < G; gx++) {
    let a = 0, r = 0, g = 0, b = 0, k = 0;
    for (let y = Math.floor(gy * s); y < Math.floor((gy + 1) * s); y++) for (let x = Math.floor(gx * s); x < Math.floor((gx + 1) * s); x++) {
      const i = (y * n + x) * 4; k++;
      if (px[i + 3] > 127) { a++; r += px[i]; g += px[i + 1]; b += px[i + 2]; }
    }
    const on = a * 2 >= k;
    mask.push(on ? 1 : 0);
    const c: [number, number, number] = a ? [r / a, g / a, b / a] : [0, 0, 0];
    rgb.push(c);
    lum.push(on ? 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2] : 0);
  }
  return { mask, lum, rgb };
}

export type Similarity = { maskIoU: number; lumCorr: number; colourDist: number };

/** Shape overlap (IoU of the masks), luminance correlation over the shared pixels, and mean RGB distance there. */
export function similarity(a: Fingerprint, b: Fingerprint): Similarity {
  let inter = 0, uni = 0; const both: number[] = [];
  for (let i = 0; i < a.mask.length; i++) { if (a.mask[i] || b.mask[i]) uni++; if (a.mask[i] && b.mask[i]) { inter++; both.push(i); } }
  const maskIoU = uni ? inter / uni : 1;
  if (both.length < 2) return { maskIoU, lumCorr: 0, colourDist: 255 };
  const ma = both.reduce((s, i) => s + a.lum[i], 0) / both.length, mb = both.reduce((s, i) => s + b.lum[i], 0) / both.length;
  let num = 0, da = 0, db = 0;
  const cds: number[] = [];
  for (const i of both) {
    const x = a.lum[i] - ma, y = b.lum[i] - mb; num += x * y; da += x * x; db += y * y;
    cds.push(Math.hypot(a.rgb[i][0] - b.rgb[i][0], a.rgb[i][1] - b.rgb[i][1], a.rgb[i][2] - b.rgb[i][2]));
  }
  // colour distance where the two differ most (top twelfth of cells): an ore's shared rock must not hide its ore
  cds.sort((p, q) => q - p);
  const top = cds.slice(0, Math.max(1, Math.ceil(cds.length / 12)));
  const cd = top.reduce((s, v) => s + v, 0) / top.length;
  const lumCorr = da > 0 && db > 0 ? num / Math.sqrt(da * db) : da === db ? 1 : 0;
  return { maskIoU: Math.round(maskIoU * 1000) / 1000, lumCorr: Math.round(lumCorr * 1000) / 1000, colourDist: Math.round(cd * 10) / 10 };
}

/** Same drawing (shape + shading structure), whatever the colours: a recolour or a trace. */
export const isNearCopy = (s: Similarity) => s.maskIoU >= 0.9 && s.lumCorr >= 0.9;
/** Same drawing AND nearly the same colours: two library variants a viewer could not tell apart. */
export const isColourLookalike = (s: Similarity) => isNearCopy(s) && s.colourDist < 40;

export type NearCopyResult = { status: "pass" | "fail" | "not_run"; matched: number | null; best: Similarity | null; message: string };

export function checkNearCopy(img: Raster, refs: readonly Fingerprint[]): NearCopyResult {
  if (!refs.length) return { status: "not_run", matched: null, best: null, message: "no vanilla reference fingerprints on this host; compute them on the build host from the server jar (never commit them)" };
  const fp = fingerprint(img);
  let best: Similarity | null = null, at = -1;
  refs.forEach((r, i) => { const s = similarity(fp, r); if (!best || s.maskIoU + s.lumCorr > best.maskIoU + best.lumCorr) { best = s; at = i; } });
  const hit = best !== null && isNearCopy(best);
  return { status: hit ? "fail" : "pass", matched: hit ? at : null, best, message: hit ? "too close to a reference texture (shape and shading match); draw it from scratch" : "no reference texture matches" };
}
