8:export const QUALITY_VERSION = "tq-1";
9:export type CheckStatus = "pass" | "warn" | "fail" | "not_run";
10:export type QualityCheck = { id: string; status: CheckStatus; value: number | null; limit: string; message: string };
11:export type QualityReport = { version: string; verdict: "pass" | "warn" | "fail"; size: number; checks: QualityCheck[]; profile?: "tile" };
12:/**
13: * "item" (default): a silhouette on a clear background (what builds generate; the JS twin implements only this).
14: * "tile": a block face / skin swatch (texture library, uploads): fully solid is expected, outline does not apply,
15: * and a `seam` check compares the wrap-around edges with the texture's own interior. TS only for now: the build
16: * service does not generate tiles yet (when it does, port the profile to services/modbuilder/textures.js).
17: */
18:export type QualityProfile = "item" | "tile";
19:
20:/** Per-size limits. Vanilla item art is 16x16 with a few ramps of 3-5 shades; bigger canvases may use a little more. */
21:const PALETTE_LIMIT: Record<number, { warn: number; fail: number }> = { 16: { warn: 32, fail: 48 }, 32: { warn: 48, fail: 96 }, 64: { warn: 64, fail: 128 } };
22:// "Grain": neighbouring solid pixels that are almost, but not exactly, the same colour (RGB distance 1..GRAIN_MAX).
23:// That is what the noise op and smooth gradients produce; hand-made pixel art uses flat clusters plus deliberate
24:// shade steps (vanilla ramps step by more than this), so a high grain ratio means noisy, muddy art.
