26:const GRAIN = { warn: 0.2, fail: 0.35 };
27:const CONTRAST = { fail: 1.6, warn: 2.5 };
28:const COVERAGE = { failLow: 0.04, warnLow: 0.1, warnHigh: 0.85 };
29:const OUTLINE_DARK = 0.12; // relative luminance at or below which a silhouette pixel reads as an outline
30:const OUTLINE_WARN = 0.5;
31:// tile profile: mean RGB step across the wrap edges / (mean interior step + SEAM_FLOOR)
32:const SEAM = { warn: 1.8, fail: 3 };
33:const SEAM_FLOOR = 6;
