39:/** `tileable: false` or `framed: true` (tile profile only) skip the seam check: a nine-slice panel or a log end is not meant to repeat. */
40:export function textureQuality(img: Raster, opts: { profile?: QualityProfile; tileable?: boolean; framed?: boolean } = {}): QualityReport {
  const outline = rim ? rimDark / rim : 0;
  if (tile) {
    // wrap seam: the step from the last column to the first (and last row to the first) against the interior steps
    let wrap = 0, wn = 0, inner = 0, inn = 0;
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      if (!opaque(x, y)) continue;
      const i = at(x, y);
      const right = (x + 1) % n, down = (y + 1) % n;
      if (opaque(right, y)) { const d = dist(i, at(right, y)); if (x === n - 1) { wrap += d; wn++; } else { inner += d; inn++; } }
      if (opaque(x, down)) { const d = dist(i, at(x, down)); if (y === n - 1) { wrap += d; wn++; } else { inner += d; inn++; } }
    }
    const seam = wn ? (wrap / wn) / ((inn ? inner / inn : 0) + SEAM_FLOOR) : 0;
    if (opts.framed) checks.push({ id: "seam", status: "not_run", value: r4(seam), limit: "unframed tiles only", message: "framed tile: repeats as a grid of bevelled slabs by design" });
    else if (opts.tileable === false) checks.push({ id: "seam", status: "not_run", value: r4(seam), limit: "tileable textures only", message: "not meant to repeat, so the wrap seam is not checked" });
    else checks.push({
      id: "seam", status: seam > SEAM.fail ? "fail" : seam > SEAM.warn ? "warn" : "pass", value: r4(seam), limit: `<= ${SEAM.warn} (fail above ${SEAM.fail})`,
      message: seam > SEAM.fail ? "the edges do not continue across the wrap; the tile will show a grid when repeated" : seam > SEAM.warn ? "the wrap edges are a little harder than the interior" : "repeats without a visible seam",
    });
    checks.push({ id: "outline", status: "not_run", value: r4(outline), limit: "items only", message: "tiles have no silhouette, so the outline rule does not apply" });
  } else checks.push({
    id: "outline", status: outline >= OUTLINE_WARN ? "pass" : "warn", value: r4(outline), limit: `>= ${OUTLINE_WARN} of the silhouette dark`,
    message: outline >= OUTLINE_WARN ? "consistent dark outline" : "the silhouette has no consistent dark outline (Style DNA: outline every item the same way)",
  });

  checks.push({ id: "vanilla_lookalike", status: "not_run", value: null, limit: "perceptual hash vs vanilla textures", message: "not built yet: needs the vanilla texture set on the build host (GAPS finding 15)" });

  const verdict = checks.some((c) => c.status === "fail") ? "fail" : checks.some((c) => c.status === "warn") ? "warn" : "pass";
  return { version: QUALITY_VERSION, verdict, size: n, checks, ...(tile ? { profile: "tile" as const } : {}) };
}

/** One line per failing check, for repair feedback and customer notices. */
export const qualityProblems = (r: QualityReport): string[] => r.checks.filter((c) => c.status === "fail").map((c) => `${c.id}: ${c.message} (value ${c.value}, limit ${c.limit})`);
