// Cyrus LEGACY item looks for Minecraft 1.21.1 (resource pack format 34), which has NO item model definitions
// (assets/<ns>/items/*.json and ItemMeta#setItemModel arrived in 1.21.2/1.21.4). The only way a plugin can give a custom
// item its own look there is the pre-1.21.4 one:
//   plugin:  new ItemStack(Material.<CARRIER>); meta.setCustomModelData(<number>)
//   pack:    assets/minecraft/models/item/<carrier>.json = the vanilla model of the carrier + `overrides`
//            [{ predicate: { custom_model_data: <number> }, model: "<ns>:item/<texture>" }, ...]
// The model writes a small manifest (assets/legacy-models.json) that binds each texture to a carrier and a number from
// the mod's own block (legacyCmdBase(namespace) + 1..999). Everything here is pure and deterministic.
// HONEST LIMITS (versionAssetLimits): this path OVERRIDES the vanilla carrier's model file, so a second pack that
// overrides the same carrier replaces ours (or ours replaces it); only the states 1.21.1 has predicates for are emitted
// (damage), the rest is refused with a message, never dropped silently.
import { getVersion, type VersionRow } from "../versions/registry";

export const LEGACY_EMITTER_VERSION = "cyrus-legacy-cmd-1";
/** Portal flag: route 1.21.1 texture requests to this path (the builder has its own MB_LEGACY_TEXTURES). Off = textures stay off on 1.21.1 as before. */
export const LEGACY_TEXTURES_FLAG = "CYRUS_LEGACY_TEXTURES";
export const legacyTexturesOn = (env: Record<string, string | undefined> = process.env) => env[LEGACY_TEXTURES_FLAG] === "1";
export const LEGACY_MANIFEST_PATH = "assets/legacy-models.json";
export const LEGACY_PACK_RANGE = { min: 34, max: 45 } as const; // 1.21.1 .. 1.21.3 still read `overrides`; 1.21.4 (46) ignores them
export const CMD_BLOCK = 1000;
const CMD_BLOCKS = 15000; // 1e6 + 15000*1000 < 2^24: every number stays exact as a float (the predicate compares floats)

/**
 * Vanilla items whose 1.21.1 item model is exactly { parent, textures.layer0 = minecraft:item/<id> } with no overrides,
 * so Cyrus can rewrite the file losslessly. Checked against the vanilla 1.21.1 client jar (test fixture
 * test/fixtures/cyrus-legacy/vanilla-1.21.1-carriers.json, written by the flight harness).
 */
export const LEGACY_CARRIERS: Readonly<Record<string, "handheld" | "generated">> = Object.freeze({
  ...Object.fromEntries(["wooden", "stone", "iron", "golden", "diamond", "netherite"].flatMap((t) => ["sword", "axe", "pickaxe", "shovel", "hoe"].map((k) => [`${t}_${k}`, "handheld" as const]))),
  stick: "handheld", blaze_rod: "handheld",
  paper: "generated", emerald: "generated", diamond: "generated", iron_ingot: "generated", gold_ingot: "generated", netherite_ingot: "generated",
  amethyst_shard: "generated", nether_star: "generated", flint: "generated", slime_ball: "generated", gunpowder: "generated",
  ghast_tear: "generated", echo_shard: "generated", heart_of_the_sea: "generated", apple: "generated", bread: "generated", cookie: "generated",
  baked_potato: "generated", golden_carrot: "generated", book: "generated",
});

export type LegacyBinding = { texture: string; base: string; cmd: number };
export type LegacyCheck = { ok: true; bindings: LegacyBinding[] } | { ok: false; errors: string[] };

function fnv1a(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h >>> 0;
}

/** The first number of this mod's block; its own numbers are base+1 .. base+999. */
export const legacyCmdBase = (namespace: string) => 1_000_000 + (fnv1a(namespace) % CMD_BLOCKS) * CMD_BLOCK;

/** True for a version that needs this path for textures (no item model definitions, legacy capability). */
export const isLegacyVersion = (v: VersionRow | string | null | undefined): boolean => {
  const row = typeof v === "string" ? getVersion(v) : v;
  return !!row && !row.capabilities.includes("itemModelDefinitions") && row.capabilities.includes("legacyCustomModelData");
};

const NAME_RE = /^[a-z][a-z0-9_]{1,31}$/;

/**
 * Validate the model's manifest { items: [{ texture, base, cmd }] }. `textures` = the mod's texture names; `required`
 * = the ones that must be bound (every texture that is not only a state texture). Never throws.
 */
export function checkLegacyManifest(raw: unknown, opts: { namespace: string; textures: readonly string[]; required?: readonly string[] }): LegacyCheck {
  const errors: string[] = [];
  const items = raw && typeof raw === "object" && Array.isArray((raw as { items?: unknown }).items) ? (raw as { items: unknown[] }).items : null;
  if (!items) return { ok: false, errors: [`${LEGACY_MANIFEST_PATH} must be {"items": [{"texture", "base", "cmd"}, ...]}`] };
  if (items.length > 24) return { ok: false, errors: [`${LEGACY_MANIFEST_PATH} binds at most 24 textures`] };
  const base = legacyCmdBase(opts.namespace);
  const bindings: LegacyBinding[] = [];
  const seenT = new Set<string>(), seenC = new Set<number>();
  items.forEach((it, i) => {
    const at = `items[${i}]`;
    const o = (it ?? {}) as Record<string, unknown>;
    const extra = Object.keys(o).filter((k) => !["texture", "base", "cmd"].includes(k));
    if (extra.length) errors.push(`${at}: unknown field ${extra[0]}`);
    const t = o.texture, b = typeof o.base === "string" ? o.base.replace(/^minecraft:/, "") : o.base, c = o.cmd;
    if (typeof t !== "string" || !NAME_RE.test(t)) { errors.push(`${at}.texture must be a texture name`); return; }
    if (!opts.textures.includes(t)) { errors.push(`${at}.texture ${t} is not a texture of this mod`); return; }
    if (seenT.has(t)) { errors.push(`${at}: ${t} is bound twice`); return; }
    if (typeof b !== "string" || !Object.prototype.hasOwnProperty.call(LEGACY_CARRIERS, b)) { errors.push(`${at}.base must be one of the legacy carrier items (${Object.keys(LEGACY_CARRIERS).slice(0, 6).join(", ")}, ...); got ${String(b)}`); return; }
    if (typeof c !== "number" || !Number.isInteger(c) || c <= base || c >= base + CMD_BLOCK) { errors.push(`${at}.cmd must be a whole number from ${base + 1} to ${base + CMD_BLOCK - 1} (this mod's block)`); return; }
    if (seenC.has(c)) { errors.push(`${at}: cmd ${c} is used twice`); return; }
// Cyrus data pack studio: what differs per Minecraft version, and the vanilla id lists (pure, server + build service).
//
// Every format difference below was VERIFIED on the real jars (2026-10-10, node-2): the vanilla data generator of
// each pinned server jar (`--reports --server`) dumped the vanilla data pack, and the same recipe / loot table /
// advancement / enchantment files were compared across versions (see docs "Cyrus data pack studio (R2)"), then
// cross-checked against vanilla-mcdoc (MIT, pinned commit in data/mcdoc-subset.json). Version strings compare
// numerically (1.21.11 > 1.21.4; 26.x > 1.21.x).
import idsData from "./data/vanilla-ids.json";
import { getVersion } from "../versions/registry";

export type McVersion = string;

/** -1 / 0 / 1 like a comparator. "1.21.2" vs "1.21.11": 2 < 11. Missing parts count as 0 (26.1 == 26.1.0). */
export function compareMc(a: string, b: string): number {
  const pa = a.split(".").map(Number), pb = b.split(".").map(Number);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const x = pa[i] ?? 0, y = pb[i] ?? 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}
export const atLeast = (v: string, min: string) => compareMc(v, min) >= 0;

/** Versions the studio can emit for: the ones whose vanilla ids were generated from the real jar. */
export const DATAPACK_VERSIONS: readonly string[] = (idsData as { versions: string[] }).versions;

export type DataPackFeatures = {
  version: string;
  format: { major: number; minor: number };
  /** <1.21.9: `pack_format` (+ no minor); >=1.21.9: `min_format` / `max_format` as [major, minor]. */
  mcmeta: "pack_format" | "min_max";
  /** <=1.21.1: ingredients are objects ({"item": id} / {"tag": id}); >=1.21.2: strings ("id" / "#tag"). */
  ingredient: "object" | "string";
  /** <=1.21.4: text-valued item components (item_name, lore) are JSON strings; >=1.21.5: text component objects. */
  componentText: "json-string" | "object";
  /** <1.21.5: advancement backgrounds are texture paths (minecraft:textures/gui/.../stone.png); >=1.21.5: ids (minecraft:gui/.../stone). */
  background: "texture-path" | "id";
  /** <26.2: entity predicates use plain keys ({"type": ...}); >=26.2: namespaced sub-predicates ({"minecraft:entity_type": ...}). */
  entityPredicate: "plain" | "sub-map";
  /** <26.1: smelting-family results are a single item (no count); >=26.1: an item stack template (count allowed). */
  cookingResultCount: boolean;
  /** smithing_transform takes `group` only before 26.1 (vanilla-mcdoc). */
  smithingGroup: boolean;
  /** <26.1 vanilla writes `count: 1` in advancement icons; 26.1+ omits it (both read the same; we mirror vanilla). */
  iconCount: boolean;
};

export type FeaturesResult = { ok: true; features: DataPackFeatures } | { ok: false; error: string };

/** Fails closed: unknown version, no verified data pack format, or no generated vanilla ids for it. */
export function dataPackFeatures(version: string): FeaturesResult {
  const row = getVersion(version);
  if (!row) return { ok: false, error: `Minecraft ${version} is not in the version registry` };
  if (!row.dataPack) return { ok: false, error: `the data pack format of Minecraft ${version} is not verified yet` };
  if (!DATAPACK_VERSIONS.includes(version)) return { ok: false, error: `Cyrus has no vanilla id list for Minecraft ${version} yet (needs a pinned server jar on the build host)` };
  return {
    ok: true,
    features: {
      version,
      format: row.dataPack,
      mcmeta: atLeast(version, "1.21.9") ? "min_max" : "pack_format",
      ingredient: atLeast(version, "1.21.2") ? "string" : "object",
      componentText: atLeast(version, "1.21.5") ? "object" : "json-string",
      background: atLeast(version, "1.21.5") ? "id" : "texture-path",
      entityPredicate: atLeast(version, "26.2") ? "sub-map" : "plain",
      cookingResultCount: atLeast(version, "26.1"),
      smithingGroup: !atLeast(version, "26.1"),
      iconCount: !atLeast(version, "26.1"),
    },
  };
}

