// The catalog service: plan gate + providers + unified search, behind injectable host seams (plan lookup, asset
// store). Cyrus reaches Nxeon ONLY through `CatalogDeps.planOf` (today: lib/cyrus/tokens/access tierOf, wired by
// the route that will call this) and the UserAssetStore. Server code calls it per request; nothing here caches
// across users.
import { canBrowse, type BrowseDecision } from "./gate";
import { searchAssets, similarAssets, type UnifiedQuery, type UnifiedResult } from "./search";
import { LIBRARY_KINDS, LIBRARY_SOURCES, type LibraryAsset, type LibraryKind, type LibraryProvider, type LibrarySource, type ProviderContext } from "./types";

export type CatalogDeps = {
  providers: readonly LibraryProvider[];
  /** the viewer's raw plan (any spelling asset-gate understands); throw or return null when unknown -> fail closed */
  planOf: (userId: string) => Promise<unknown>;
};
export type BrowseRequest = { userId: string | null; projectId?: string | null; query?: UnifiedQuery };
export type Denial = { kind: LibraryKind; source: LibrarySource; code: Exclude<BrowseDecision, { ok: true }>["code"]; reason: string; needs?: string };
export type BrowseResponse = UnifiedResult & { denied: Denial[] };

async function visible(deps: CatalogDeps, req: BrowseRequest, kinds: readonly LibraryKind[]): Promise<{ assets: LibraryAsset[]; denied: Denial[] }> {
  const denied: Denial[] = [];
  if (!req.userId) {
    for (const kind of kinds) denied.push({ kind, source: "builtin", code: "sign_in", reason: "Sign in to browse the asset library." });
    return { assets: [], denied };
  }
  let plan: unknown = null;
  try { plan = await deps.planOf(req.userId); } catch { plan = null; } // unknown plan: fail closed (project assets stay visible)
  const viewer = { signedIn: true, plan };
  const ctx: ProviderContext = { userId: req.userId, projectId: req.projectId ?? null };
  const assets: LibraryAsset[] = [];
  for (const kind of kinds) {
    const allowed = new Set<LibrarySource>();
    for (const source of LIBRARY_SOURCES) {
      if (source === "project" && !ctx.projectId) continue;
      if (!deps.providers.some((p) => p.kind === kind && p.sources.includes(source))) continue;
      const d = canBrowse(viewer, kind, source);
      if (d.ok) allowed.add(source);
      else denied.push({ kind, source, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
    }
    if (!allowed.size) continue;
    for (const p of deps.providers) if (p.kind === kind) for (const a of await p.list(ctx, allowed)) if (allowed.has(a.source)) assets.push(a);
  }
