  version: string; itemDefinitions: string[]; blockstates: string[]; particles: string[]; equipment: string[]; atlases: string[];
  shaders: string[]; postEffects: string[]; entityLangKeys: string[]; builtinDatapacks: string[];
  itemModelTypes: Record<string, number>; itemModelProperties: Record<string, string[]>;
  itemDefinitionRoots: Record<string, unknown>; itemRangeDispatch: Record<string, { property: string; scale: number; thresholds: number[] }[]>;
  data: Record<string, string[]>; formatFacts: Record<string, Record<string, number>>; counts: Record<string, number>;
  source: { zipSha256: string; zipName: string };
};
export type VanillaIndex = {
  version: string; registries: VanillaRegistries; textures: Record<string, TextureRow>; models: Record<string, ModelRow>;
  sounds: { events: Record<string, SoundEventRow>; files: string[] };
};

const RAW: Record<string, () => VanillaIndex> = {
  "26.1.2": () => ({
    version: "26.1.2",
    registries: reg2612 as unknown as VanillaRegistries,
    textures: (tex2612 as unknown as { textures: Record<string, TextureRow> }).textures,
    models: (mod2612 as unknown as { models: Record<string, ModelRow> }).models,
    sounds: snd2612 as unknown as VanillaIndex["sounds"],
  }),
};
/** Versions with a distilled index. Everything else: lookups return null / "not_indexed" (callers fail closed or skip). */
export const VANILLA_INDEX_VERSIONS: readonly string[] = Object.keys(RAW);
const cache = new Map<string, VanillaIndex>();
export function vanillaIndex(version: string): VanillaIndex | null {
  if (!RAW[version]) return null;
  let v = cache.get(version);
  if (!v) { v = RAW[version](); cache.set(version, v); }
  return v;
}

const sets = new Map<string, Set<string>>();
function setOf(version: string, key: string, list: () => readonly string[]): Set<string> {
  const k = `${version}|${key}`;
  let s = sets.get(k);
  if (!s) { s = new Set(list()); sets.set(k, s); }
  return s;
}
const bare = (id: string) => id.replace(/^#/, "").replace(/^minecraft:/, "");

/** "minecraft:item/stick", "item/stick" or "assets/minecraft/textures/item/stick.png" -> facts, or null. */
export function vanillaTexture(version: string, ref: string): { path: string; width: number; height: number; animated: boolean; flags: string } | null {
  const ix = vanillaIndex(version);
  if (!ix) return null;
  const p = bare(ref).replace(/^assets\/minecraft\/textures\//, "").replace(/\.png$/, "");
  const row = ix.textures[p];
  return row ? { path: p, width: row[0], height: row[1], animated: row[2].includes("a"), flags: row[2] } : null;
}

export function vanillaModel(version: string, id: string): ModelRow | null {
  const ix = vanillaIndex(version);
  return ix ? ix.models[bare(id).replace(/^assets\/minecraft\/models\//, "").replace(/\.json$/, "")] ?? null : null;
}

/** builtin/* parents end a chain (the game supplies them). */
export const BUILTIN_PARENTS = ["builtin/generated", "builtin/entity"] as const;

/** The parent chain of a model (child first). error when a parent is unknown or the chain loops. */
export function parentChain(version: string, id: string, extra: Record<string, ModelRow> = {}): { ok: true; chain: string[] } | { ok: false; error: string; chain: string[] } {
  const chain: string[] = [];
  let cur: string | undefined = bare(id);
  while (cur) {
    if (chain.includes(cur)) return { ok: false, error: `model parent loop at ${cur}`, chain };
    chain.push(cur);
    if ((BUILTIN_PARENTS as readonly string[]).includes(cur)) break;
    const row: ModelRow | null = extra[cur] ?? vanillaModel(version, cur);
    if (!row) return { ok: false, error: `model ${cur} is neither vanilla ${version} nor in this pack`, chain };
    cur = row.p ? bare(row.p) : undefined;
    if (chain.length > 32) return { ok: false, error: "model parent chain deeper than 32", chain };
  }
  return { ok: true, chain };
}

export type Transform = { rotation: number[]; translation: number[]; scale: number[] };
/** Display per context after parent merging (a child's context replaces the parent's whole entry, as the game does). */
export function resolvedDisplay(version: string, id: string, extra: Record<string, ModelRow> = {}): Record<string, Transform> | null {
  const c = parentChain(version, id, extra);
  if (!c.ok) return null;
  const out: Record<string, Transform> = {};
  for (const m of [...c.chain].reverse()) {
    const d = (extra[m] ?? vanillaModel(version, m))?.d;
    if (d) for (const [ctx, t] of Object.entries(d)) out[ctx] = { rotation: t.rotation ?? [0, 0, 0], translation: t.translation ?? [0, 0, 0], scale: t.scale ?? [1, 1, 1] };
  }
  return out;
}

export function vanillaSoundEvent(version: string, ev: string): SoundEventRow | null {
  return vanillaIndex(version)?.sounds.events[bare(ev)] ?? null;
}

export const isVanillaItem = (version: string, id: string) => !!vanillaIndex(version) && setOf(version, "item", () => vanillaIndex(version)!.registries.itemDefinitions).has(bare(id));
export const isVanillaBlock = (version: string, id: string) => !!vanillaIndex(version) && setOf(version, "block", () => vanillaIndex(version)!.registries.blockstates).has(bare(id));
/** A data registry id: registry = "recipe", "loot_table", "worldgen/biome", "tags/item", ... */
export const isVanillaData = (version: string, registry: string, id: string) =>
  !!vanillaIndex(version) && setOf(version, `data:${registry}`, () => vanillaIndex(version)!.registries.data[registry] ?? []).has(bare(id));

export type VanillaPathHit = { kind: "texture" | "texture_meta" | "model" | "item_definition" | "blockstate" | "sound" | "sounds_json" | "particle" | "shader" | "atlas" | "equipment" | "data"; registry?: string; id: string };

/**
 * Is this pack path a vanilla file of `version` (so shipping it OVERRIDES vanilla)? Resource pack paths
 * (assets/minecraft/...) and data pack paths (data/minecraft/...). null = not vanilla, or the version is not indexed
 * (use vanillaIndex(version) to tell the two apart). Never throws.
 */
export function vanillaPath(version: string, packPath: string): VanillaPathHit | null {
  const ix = vanillaIndex(version);
  if (!ix || typeof packPath !== "string") return null;
  const p = packPath.replace(/^\/+/, "");
  let m: RegExpMatchArray | null;
  if ((m = p.match(/^assets\/minecraft\/textures\/(.+)\.png(\.mcmeta)?$/))) return ix.textures[m[1]] ? { kind: m[2] ? "texture_meta" : "texture", id: m[1] } : null;
  if ((m = p.match(/^assets\/minecraft\/models\/(.+)\.json$/))) return ix.models[m[1]] ? { kind: "model", id: m[1] } : null;
  if ((m = p.match(/^assets\/minecraft\/items\/(.+)\.json$/))) return isVanillaItem(version, m[1]) ? { kind: "item_definition", id: m[1] } : null;
  if ((m = p.match(/^assets\/minecraft\/blockstates\/(.+)\.json$/))) return isVanillaBlock(version, m[1]) ? { kind: "blockstate", id: m[1] } : null;
  if ((m = p.match(/^assets\/minecraft\/sounds\/(.+)\.ogg$/))) return setOf(version, "soundfile", () => ix.sounds.files).has(m[1]) ? { kind: "sound", id: m[1] } : null;
  if (p === "assets/minecraft/sounds.json") return { kind: "sounds_json", id: "sounds.json" };
  if ((m = p.match(/^assets\/minecraft\/particles\/(.+)\.json$/))) return setOf(version, "particle", () => ix.registries.particles).has(m[1]) ? { kind: "particle", id: m[1] } : null;
  if ((m = p.match(/^assets\/minecraft\/shaders\/(.+)$/))) return setOf(version, "shader", () => ix.registries.shaders).has(m[1]) ? { kind: "shader", id: m[1] } : null;
  if ((m = p.match(/^assets\/minecraft\/atlases\/(.+)\.json$/))) return setOf(version, "atlas", () => ix.registries.atlases).has(m[1]) ? { kind: "atlas", id: m[1] } : null;
  if ((m = p.match(/^assets\/minecraft\/equipment\/(.+)\.json$/))) return setOf(version, "equipment", () => ix.registries.equipment).has(m[1]) ? { kind: "equipment", id: m[1] } : null;
  if ((m = p.match(/^data\/minecraft\/(.+)\.(json|nbt)$/))) {
    const rest = m[1];
    // longest registry prefix wins (tags/worldgen/biome before tags/worldgen, worldgen/biome before worldgen)
    const regs = Object.keys(ix.registries.data).filter((r) => rest.startsWith(r + "/")).sort((a, b) => b.length - a.length);
    for (const r of regs) { const id = rest.slice(r.length + 1); if (isVanillaData(version, r, id)) return { kind: "data", registry: r, id }; }
  }
  return null;
}

