// Cyrus PRIVATE vanilla reference (SERVER ONLY): the sha256 manifest of every vanilla file and the 16x16 texture
// fingerprints, written by /tank/cyrus-library-staging/_reference/tools/mc_index.py. These never enter git, a build, a
// library or a customer download. Read only when CYRUS_VANILLA_REFERENCE_DIR points at the reference directory
// (<dir>/<version>/{files,fingerprints}.json). Not configured / unreadable = null: every caller reports "not_run" or
// refuses (fail closed); nothing here ever claims a file is (or is not) vanilla without the data.
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join, resolve } from "node:path";
import type { Fingerprint } from "../../texture-library/lookalike";

export const VANILLA_REFERENCE_ENV = "CYRUS_VANILLA_REFERENCE_DIR";
const VERSION_RE = /^\d+\.\d+(\.\d+)?$/;
const SHA_RE = /^[0-9a-f]{64}$/;

export type VanillaFileHit = { version: string; path: string; size: number };
export type VanillaReference = {
  dir: string;
  versions: string[];
  /** sha256 -> every vanilla file with those exact bytes (identical files recur across paths and versions) */
  bySha: Map<string, VanillaFileHit[]>;
  /** path -> sha per version */
  byPath: Map<string, Map<string, string>>;
  fingerprints: { version: string; path: string; fp: Fingerprint }[];
};

const cache = new Map<string, VanillaReference | null>();

/** Load the private reference (cached per directory). null when not configured or unreadable. */
export function loadVanillaReference(env: Record<string, string | undefined> = process.env): VanillaReference | null {
  const raw = env[VANILLA_REFERENCE_ENV];
  if (!raw) return null;
  const dir = resolve(raw);
  if (cache.has(dir)) return cache.get(dir)!;
  let ref: VanillaReference | null = null;
  try {
    if (existsSync(dir)) {
      ref = { dir, versions: [], bySha: new Map(), byPath: new Map(), fingerprints: [] };
      for (const v of readdirSync(dir).filter((x) => VERSION_RE.test(x)).sort()) {
        const fp = join(dir, v, "files.json");
        if (!existsSync(fp)) continue;
        const files = (JSON.parse(readFileSync(fp, "utf8")) as { files: Record<string, [string, number]> }).files;
        const byPath = new Map<string, string>();
        for (const [path, [sha, size]] of Object.entries(files)) {
          if (!SHA_RE.test(sha)) continue;
          byPath.set(path, sha);
          const hits = ref.bySha.get(sha) ?? [];
          hits.push({ version: v, path, size });
          ref.bySha.set(sha, hits);
        }
        ref.byPath.set(v, byPath);
        ref.versions.push(v);
        const fpp = join(dir, v, "fingerprints.json");
        if (existsSync(fpp)) for (const r of (JSON.parse(readFileSync(fpp, "utf8")) as { fingerprints: { path: string; fp: Fingerprint }[] }).fingerprints) ref.fingerprints.push({ version: v, ...r });
      }
      if (!ref.versions.length) ref = null;
    }
  } catch { ref = null; }
  cache.set(dir, ref);
  return ref;
}
/** tests */
export const _resetVanillaReferenceCache = () => cache.clear();

/** Which vanilla file(s) these bytes are ("vanilla 26.1.2 assets/minecraft/textures/item/stick.png"). [] = not vanilla (as far as the reference knows). */
export function lookupVanillaSha(ref: VanillaReference, sha256: string): VanillaFileHit[] {
  return SHA_RE.test(sha256) ? ref.bySha.get(sha256) ?? [] : [];
}

/** Is `sha256` exactly the vanilla file at `path` in `version`? */
export function isVanillaFile(ref: VanillaReference, version: string, path: string, sha256: string): boolean {
  return ref.byPath.get(version)?.get(path) === sha256;
}

