// Cyrus R42 Minecraft reference: the distilled vanilla index (lib/cyrus/versions/vanilla) agrees with the jar-derived
// ids and with what the emitters assume; the private reference loader fails closed. No Mojang file is read here: the
// private reference is exercised with a synthetic fixture written to a temp dir.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { isVanillaData, isVanillaItem, parentChain, resolvedDisplay, vanillaIndex, vanillaModel, vanillaPath, vanillaSoundEvent, vanillaTexture, VANILLA_INDEX_VERSIONS } from "../lib/cyrus/versions/vanilla";
import { loadVanillaReference, lookupVanillaSha, isVanillaFile, _resetVanillaReferenceCache, VANILLA_REFERENCE_ENV } from "../lib/cyrus/versions/vanilla/reference.server";
import { dataPackFeatures, vanillaIds } from "../lib/cyrus/datapack/versions";
import { BOW_FULL, CROSSBOW_FULL, GENERATED_FULL, HANDHELD_FULL } from "../lib/cyrus/itemmodel/display";
import { DISPLAY_CONTEXTS } from "../lib/cyrus/itemmodel/spec";
import { USE_DURATION_SCALE } from "../lib/cyrus/itemmodel/emit";
import { bowTemplate } from "../lib/cyrus/itemmodel/templates";
import { LEGACY_CARRIERS } from "../lib/cyrus/itemmodel/legacy";

const V = "26.1.2";
const ix = vanillaIndex(V)!;

describe("vanilla index: distilled facts only", () => {
  it("indexes 26.1.2 and nothing it cannot back", () => {
    assert.deepEqual([...VANILLA_INDEX_VERSIONS], ["26.1.2"]);
    assert.equal(vanillaIndex("1.21.1"), null);
    assert.equal(ix.registries.counts.items, 1506);
    assert.equal(ix.registries.counts.soundEvents, 1902);
  });
  it("the committed directory holds JSON facts and code only (never a Mojang file)", () => {
    const dir = path.join(__dirname, "..", "lib", "cyrus", "versions", "vanilla");
    const walk = (d: string): string[] => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]));
    for (const f of walk(dir)) {
      assert.match(f, /\.(json|ts)$/, `${f} is not a facts file`);
      if (f.endsWith(".json")) assert.doesNotMatch(fs.readFileSync(f, "utf8"), /[A-Za-z0-9+/]{400,}/, `${f} carries an encoded blob`);
    }
  });
});

describe("vanilla index vs the jar's data generator (vanilla-ids.json)", () => {
  const same = (kind: Parameters<typeof vanillaIds>[0], list: readonly string[], known: string[] = []) => {
    const jar = vanillaIds(kind, V), zip = new Set(list);
    assert.deepEqual([...jar].filter((x) => !zip.has(x)).sort(), [], `${kind}: in the jar, not in the assets`);
    assert.deepEqual([...zip].filter((x) => !jar.has(x)).sort(), known, `${kind}: in the assets, not in the jar`);
  };
  it("items, loot tables, recipes, advancements, worldgen and tags match exactly", () => {
    same("item", ix.registries.itemDefinitions);
    for (const [k, r] of [["loot_table", "loot_table"], ["recipe", "recipe"], ["advancement", "advancement"], ["biome", "worldgen/biome"], ["structure", "worldgen/structure"],
      ["configured_feature", "worldgen/configured_feature"], ["placed_feature", "worldgen/placed_feature"], ["structure_set", "worldgen/structure_set"], ["template_pool", "worldgen/template_pool"],
      ["tag/item", "tags/item"], ["tag/block", "tags/block"], ["tag/biome", "tags/worldgen/biome"], ["enchantment", "enchantment"]] as const) same(k, ix.registries.data[r] ?? []);
  });
  it("known asset-vs-registry differences stay known (AM-vanilla-diff.md)", () => {
    same("block", ix.registries.blockstates, ["glow_item_frame", "item_frame"]); // blockstates for the item-frame ENTITIES' models
    same("sound_event", Object.keys(ix.sounds.events).filter((e) => e !== "entity.chicken_picky.step"));
    assert.ok(vanillaIds("sound_event", V).has("intentionally_empty") && !vanillaSoundEvent(V, "intentionally_empty"));
  });
});

describe("emitter assumptions hold for 26.1.2", () => {
  it("data pack features match the vanilla files' own shapes", () => {
    const f = dataPackFeatures(V);
    assert.ok(f.ok);
    const ff = ix.registries.formatFacts;
    assert.equal(f.features.ingredient, "string"); assert.ok(ff.ingredientForm.string > 1000 && !ff.ingredientForm.object);
    assert.equal(f.features.background, "id"); assert.ok(ff.advBackground.id > 0 && !ff.advBackground["texture-path"]);
