    for (const s of Array.isArray(def?.sounds) ? def!.sounds! : []) {
      const o = typeof s === "string" ? { name: s } : (s as { name?: unknown; type?: unknown });
      if (typeof o?.name !== "string") { issues.push({ code: "sound_entry_shape", severity: "error", path: `${at}#${ev}`, message: "a sound entry needs a name" }); continue; }
      if (o.type === "event") { if (!o.name.includes(":") || o.name.startsWith("minecraft:")) { if (!vanillaSoundEvent(version, o.name)) issues.push({ code: "sound_event_ref_unknown", severity: "error", path: `${at}#${ev}`, message: `refers to the event ${o.name}, which vanilla ${version} does not have` }); } continue; }
      const [ns, name] = o.name.includes(":") ? o.name.split(":", 2) : ["minecraft", o.name];
      if (ns === "minecraft" ? !vanillaFiles.has(name) && !pack.has(`minecraft:${name}`) : packSounds.length > 0 && !pack.has(`${ns}:${name}`))
        issues.push({ code: "sound_file_missing", severity: "error", path: `${at}#${ev}`, message: `${ns}:${name}.ogg is neither a vanilla ${version} sound nor in this pack` });
    }
  }
  return { status: "checked", version, issues };
}

const ROLE_WORDS: Record<string, string[]> = {
  hurt: ["hurt"], death: ["death"], ambient: ["ambient", "idle"], step: ["step"], attack: ["attack", "strong", "sweep"], spawn: ["spawn", "summon"],
  fire: ["shoot", "throw", "fire"], reload: ["load", "loading_end", "loading_middle", "loading_start"], ui: ["click", "button", "toast"], ability: ["cast", "use", "activate"],
};
const toks = (s: string) => s.toLowerCase().replace(/^minecraft:/, "").split(/[^a-z0-9]+/).filter(Boolean);

/** Ranked vanilla events a custom sound could replace/extend. `name` = the sound's set/event words ("zombie.hurt", "banshee_wail"). */
export function suggestVanillaSounds(version: string, name: string, opts: { role?: string; limit?: number } = {}): { event: string; score: number; subtitle: string | null; files: number; how: "extend" | "replace" }[] {
  const ix = vanillaIndex(version);
  if (!ix) return [];
  const want = new Set(toks(name));
  const roleWords = opts.role ? ROLE_WORDS[opts.role] ?? [opts.role] : [];
  const out: { event: string; score: number; subtitle: string | null; files: number; how: "extend" | "replace" }[] = [];
  for (const [ev, row] of Object.entries(ix.sounds.events)) {
    const t = toks(ev);
    let score = 0;
    for (const w of t) if (want.has(w)) score += 3; else for (const x of want) if (x.length >= 4 && (w.startsWith(x) || x.startsWith(w))) { score += 1; break; }
    if (roleWords.length && roleWords.some((r) => t.includes(r))) score += 2;
    if (!score) continue;
    out.push({ event: `minecraft:${ev}`, score, subtitle: row.sub ?? null, files: row.s.length, how: row.s.length > 1 ? "extend" : "replace" });
  }
  return out.sort((a, b) => b.score - a.score || a.event.localeCompare(b.event)).slice(0, Math.max(1, Math.min(10, opts.limit ?? 5)));
}

const CONTEXTS_26 = ["gui", "ground", "fixed", "head", "firstperson_righthand", "firstperson_lefthand", "thirdperson_righthand", "thirdperson_lefthand", "on_shelf"];

/** Models in a pack: parent chains resolve (vanilla, builtin or the pack), display contexts and values are sane, minecraft: texture refs exist. */
export function checkModels(version: string, files: readonly { path: string; json: unknown }[], packTextures: readonly string[] = []): VReport {
  if (!vanillaIndex(version)) return notRun(version);
  const issues: VIssue[] = [];
  const extra: Record<string, ModelRow> = {};
  const ids: [string, string, Record<string, unknown>][] = [];
  for (const f of files) {
    const m = f.path.match(/^assets\/([a-z0-9_.-]+)\/models\/(.+)\.json$/);
    if (!m || !f.json || typeof f.json !== "object") continue;
    const j = f.json as Record<string, unknown>;
    const id = m[1] === "minecraft" ? m[2] : `${m[1]}:${m[2]}`;
    extra[id] = { ...(typeof j.parent === "string" ? { p: j.parent.startsWith("minecraft:") ? bare(j.parent) : j.parent } : {}), ...(j.display ? { d: j.display as ModelRow["d"] } : {}) };
    ids.push([id, f.path, j]);
  }
  const packTex = new Set(packTextures);
  for (const [id, path, j] of ids) {
    if (typeof j.parent === "string") {
      const c = parentChain(version, id, extra);
      if (!c.ok) issues.push({ code: "model_parent", severity: "error", path, message: c.error });
      else if (!j.elements && !c.chain.some((x) => (BUILTIN_PARENTS as readonly string[]).includes(x)) && !c.chain.some((x) => (extra[x] ? false : (vanillaModel(version, x)?.e ?? 0) > 0)))
        issues.push({ code: "model_empty", severity: "warn", path, message: "neither this model nor its parents have elements or a builtin parent: it renders nothing" });
    } else if (!j.elements) issues.push({ code: "model_empty", severity: "warn", path, message: "no parent and no elements: it renders nothing" });
    if (j.display && typeof j.display === "object") for (const [ctx, t] of Object.entries(j.display as Record<string, { rotation?: unknown; translation?: unknown; scale?: unknown }>)) {
      if (!CONTEXTS_26.includes(ctx)) { issues.push({ code: "display_context", severity: "error", path, message: `unknown display context ${ctx}` }); continue; }
      const v3 = (x: unknown) => Array.isArray(x) && x.length === 3 && x.every((n) => typeof n === "number" && Number.isFinite(n));
      for (const k of ["rotation", "translation", "scale"] as const) if (t?.[k] !== undefined && !v3(t[k])) issues.push({ code: "display_value", severity: "error", path, message: `${ctx}.${k} must be three numbers` });
      if (v3(t?.translation) && (t!.translation as number[]).some((n) => Math.abs(n) > 80)) issues.push({ code: "display_clamped", severity: "warn", path, message: `${ctx}.translation beyond +-80 is clamped by the game` });
      if (v3(t?.scale) && (t!.scale as number[]).some((n) => n > 4 || n < 0)) issues.push({ code: "display_clamped", severity: "warn", path, message: `${ctx}.scale outside 0..4 is clamped by the game` });
    }
    if (j.textures && typeof j.textures === "object") for (const [k, ref] of Object.entries(j.textures as Record<string, unknown>)) {
      if (typeof ref !== "string" || ref.startsWith("#")) continue;
      const ns = ref.includes(":") ? ref.split(":")[0] : "minecraft";
      if (ns === "minecraft" ? !vanillaTexture(version, ref) && !packTex.has(`minecraft:${bare(ref)}`) : packTextures.length > 0 && !packTex.has(ref))
        issues.push({ code: "texture_missing", severity: "error", path, message: `textures.${k} = ${ref} is neither a vanilla ${version} texture nor in this pack (missing-texture checkerboard)` });
    }
  }
  return { status: "checked", version, issues };
}

/** The legacy (1.21.1) CMD carriers, checked against an INDEXED version's models: each must still be a lossless rewrite. */
export function verifyLegacyCarriers(indexVersion: string): VReport & { checked: number } {
  if (!vanillaIndex(indexVersion)) return { ...notRun(indexVersion), checked: 0 };
  const issues: VIssue[] = [];
  for (const [id, kind] of Object.entries(LEGACY_CARRIERS)) {
    const m = vanillaModel(indexVersion, `item/${id}`);
    const path = `assets/minecraft/models/item/${id}.json`;
    if (!m) { issues.push({ code: "carrier_missing", severity: "error", path, message: `${id} has no item model in ${indexVersion}` }); continue; }
    const extraKeys = Object.keys(m).filter((k) => !["p", "t"].includes(k));
    if (m.p !== `minecraft:item/${kind}` && m.p !== `item/${kind}`) issues.push({ code: "carrier_parent", severity: "error", path, message: `parent is ${m.p}, Cyrus writes item/${kind}` });
    if (JSON.stringify(m.t) !== JSON.stringify({ layer0: `minecraft:item/${id}` })) issues.push({ code: "carrier_textures", severity: "error", path, message: "textures are not exactly { layer0: minecraft:item/<id> }" });
    if (extraKeys.length) issues.push({ code: "carrier_extra", severity: "error", path, message: `model has ${extraKeys.join(", ")} that the rewrite would drop` });
  }
  return { status: "checked", version: indexVersion, issues, checked: Object.keys(LEGACY_CARRIERS).length };
}

/** Everything for one built pack (resource + data files), for the Test Flight note and the eval rubric. */
export function vanillaPackReport(version: string, files: readonly { path: string; json?: unknown }[], opts: { expected?: readonly string[] } = {}): VReport & { counts: { error: number; warn: number; info: number } } {
  if (!vanillaIndex(version)) return { ...notRun(version), counts: { error: 0, warn: 0, info: 0 } };
  const issues: VIssue[] = [...vanillaOverrides(version, files, opts).issues];
  const packTextures = files.map((f) => f.path.match(/^assets\/([a-z0-9_.-]+)\/textures\/(.+)\.png$/)).filter((m): m is RegExpMatchArray => !!m).map((m) => `${m[1]}:${m[2]}`);
  const packSounds = files.map((f) => f.path.match(/^assets\/([a-z0-9_.-]+)\/sounds\/(.+)\.ogg$/)).filter((m): m is RegExpMatchArray => !!m).map((m) => `${m[1]}:${m[2]}`);
  issues.push(...checkModels(version, files.filter((f) => f.json !== undefined) as { path: string; json: unknown }[], packTextures).issues);
  for (const f of files) { const m = f.path.match(/^assets\/([a-z0-9_.-]+)\/sounds\.json$/); if (m && f.json !== undefined) issues.push(...checkSoundsJson(version, m[1], f.json, packSounds).issues); }
  const counts = { error: 0, warn: 0, info: 0 };
  for (const i of issues) counts[i.severity]++;
  return { status: "checked", version, issues, counts };
}

