// Run the vanilla validators (./validate.ts) over BUILT pack zips (resource pack + data packs) and keep a small summary
// for ModBuild.result.assets.vanilla, the Test Flight note and the eval rubric. Pure apart from zip reading; never throws.
import { DEFAULT_ZIP_LIMITS, indexZip, readEntry } from "../../inventory/zipread";
import { vanillaIndex } from "./index";
import { vanillaPackReport, type VIssue } from "./validate";

export const VANILLA_CHECK_VERSION = "vref-1";
export type VanillaSummary = {
  version: string; check: string; status: "checked" | "not_run"; reason?: string;
  counts: { error: number; warn: number; info: number };
  /** warnings and errors first, at most 12, messages clipped */
  issues: Pick<VIssue, "code" | "severity" | "path" | "message">[];
};

/** Files of one zip as { path, json? } (json parsed for .json / .mcmeta under 1 MB). Unreadable zip = []. */
export function zipFiles(buf: Buffer): { path: string; json?: unknown }[] {
  const z = indexZip(buf, DEFAULT_ZIP_LIMITS);
  if (!z.ok) return [];
  const out: { path: string; json?: unknown }[] = [];
  for (const e of z.zip.entries) {
    if (e.name.endsWith("/")) continue;
    const row: { path: string; json?: unknown } = { path: e.name };
    if (/\.json$/.test(e.name)) { const r = readEntry(z.zip, e, 1024 * 1024); if (r.ok) try { row.json = JSON.parse(r.data.toString("utf8")); } catch { /* left without json */ } }
    out.push(row);
  }
  return out;
}

export function vanillaSummary(version: string, zips: readonly Buffer[], opts: { expected?: readonly string[] } = {}): VanillaSummary {
  if (!vanillaIndex(version)) return { version, check: VANILLA_CHECK_VERSION, status: "not_run", reason: `no vanilla reference index for Minecraft ${version}`, counts: { error: 0, warn: 0, info: 0 }, issues: [] };
  const files = zips.flatMap((z) => zipFiles(z));
  const r = vanillaPackReport(version, files, opts);
  const rank = { error: 0, warn: 1, info: 2 } as const;
  const issues = [...r.issues].sort((a, b) => rank[a.severity] - rank[b.severity]).filter((i) => i.severity !== "info").slice(0, 12)
    .map((i) => ({ code: i.code, severity: i.severity, path: i.path.slice(0, 160), message: i.message.slice(0, 240) }));
  return { version, check: VANILLA_CHECK_VERSION, status: r.status, counts: r.counts, issues };
}

/** One customer-facing notice for a summary with warnings/errors, or null. */
export function vanillaNotice(s: VanillaSummary | null | undefined): string | null {
  if (!s || s.status !== "checked" || !(s.counts.error + s.counts.warn)) return null;
  const over = s.issues.filter((i) => i.code === "vanilla_override" || i.code === "vanilla_tag_replace").length;
  return `Vanilla check (Minecraft ${s.version}): ${s.counts.error} problem(s), ${s.counts.warn} warning(s)${over ? `; ${over} file(s) replace vanilla Minecraft files for every player` : ""}.`;
}

