// Catalog tools in a build (wiring of ./tools.ts into the build service; OFF unless CYRUS_CATALOG_TOOLS=1).
//
// The build container cannot reach the portal, so the portal runs the REAL gated tools here (catalogSearch +
// catalogGet: plan tier, licence tiers per plan, proprietary clearance, published only) for queries derived from the
// request text, and sends the answers as a bounded POOL (`SvcCatalogOffer`). Inside the build, services/modbuilder/
// catalog-mcp.js serves catalog_search / catalog_get over that pool only, with the same tool definitions
// (CATALOG_TOOLS) and the same ~1k-token result cap. What the model picks comes back as ModSpec asset slots
// ({ source: "library", libraryRef: "cat:<sha256>" }); `librarySlotsFromService` re-checks them on the way in.
//
// Nothing here delivers library asset BYTES into a pack (not built): a pick is recorded on the build. Before any
// delivery uses a slot it must go through resolveLibrarySlot() again (plan may have changed).
// Byte-identical rule: flag off, no index, or a plan that may use nothing -> null, and the request is unchanged.
// HOST SEAM: plan, index, clearance and "is the service new enough" all come in as inputs; no Nxeon imports.
import { ASSET_KINDS, LIBRARY_REF_RE, SLOT_ID_RE, type AssetSlot } from "../../engine-core/spec";
import { queryWords } from "../search";
import type { CatalogKind } from "./entry";
import { docFields, type CatalogIndex } from "./retrieval";
import { access, catalogGet, catalogSearch, CATALOG_TOOLS, RESULT_CHAR_BUDGET, SEARCH_LIMIT_MAX, type ToolContext } from "./tools";

export const CATALOG_OFFER_VERSION = "cat-offer-1";
/** pool size and the whole offer's JSON size (services/modbuilder/catalog.js refuses > 32 entries / 96 KiB) */
export const POOL_MAX = 24;
export const OFFER_CHAR_BUDGET = 64 * 1024;
export const MAX_QUERIES = 16;
/** wall-clock cap for building the pool (the SQLite backend has slow broad queries) */
export const OFFER_TIME_BUDGET_MS = 2500;
export const PICKS_MAX = 12;

export type CatalogPoolItem = { id: string; ref: string; kind: CatalogKind; q: number; rank: number; words: string[]; row: Record<string, unknown>; detail: string };
export type SvcCatalogOffer = {
  v: typeof CATALOG_OFFER_VERSION; game: string | null;
  tools: { name: string; description: string; input_schema: unknown }[];
  resultCharBudget: number; searchLimitMax: number; pool: CatalogPoolItem[];
};

/** Deterministic search phrases from the request: adjacent word pairs first (precise), then single words. */
export function offerQueries(text: string, max = MAX_QUERIES): string[] {
  const w = [...new Set(queryWords(text).filter((x) => x.length >= 3 && !/^\d+$/.test(x)))].slice(0, 24);
  const out: string[] = [];
  for (let i = 0; i + 1 < w.length && out.length < Math.ceil(max / 2); i++) out.push(`${w[i]} ${w[i + 1]}`);
  for (const x of w) { if (out.length >= max) break; out.push(x); }
  return out;
}

export type OfferInput = { index: CatalogIndex; plan: unknown; game: string | null; proprietaryCleared: boolean; text: string; now?: () => number };

/** The pool for one build, or null when this plan may use nothing / nothing matched. */
export async function buildCatalogOffer(i: OfferInput): Promise<SvcCatalogOffer | null> {
  const a = access(i.plan, i.proprietaryCleared);
  if (!a.plan || !a.kinds.length || !a.tiers.length) return null;
  const ctx: ToolContext = { index: i.index, plan: i.plan, game: i.game, proprietaryCleared: i.proprietaryCleared };
  const now = i.now ?? Date.now;
  const t0 = now();
  const score = new Map<string, number>();
  const rowOf = new Map<string, Record<string, unknown>>();
  for (const q of offerQueries(i.text)) {
    if (now() - t0 > OFFER_TIME_BUDGET_MS) break;
    const r = await catalogSearch({ query: q, limit: SEARCH_LIMIT_MAX }, ctx);
    if (!r.ok) continue;
    const rows = (JSON.parse(r.content) as { rows?: (Record<string, unknown> & { id: string })[] }).rows ?? [];
    const weight = q.includes(" ") ? 2 : 1;
    rows.forEach((row, n) => { score.set(row.id, (score.get(row.id) ?? 0) + weight / (n + 1)); if (!rowOf.has(row.id)) rowOf.set(row.id, row); });
  }
  if (!score.size) return null;
  const ranked = [...score.entries()].sort((x, y) => y[1] - x[1] || (x[0] < y[0] ? -1 : 1));
  const top = ranked[0][1];
  const pool: CatalogPoolItem[] = [];
  let chars = 0;
  for (const [id, s] of ranked) {
    if (pool.length >= POOL_MAX) break;
    const g = await catalogGet({ id }, ctx); // gated again: anything the plan may not use answers not_found
    if (!g.ok) continue;
    const detail = JSON.parse(g.content) as { ref: string };
    const e = await i.index.get(detail.ref.slice(4));
    if (!e) continue;
    const row = rowOf.get(id) ?? { id, t: e.title, k: e.kind, q: e.quality.score };
    const f = docFields(e);
    const words = [...new Set([...f.title, ...f.tags, ...f.useFor, ...f.categories, ...f.freeTags, ...f.description, e.kind].flatMap((x) => String(x).toLowerCase().split(/[^a-z0-9-]+/)).filter((x) => x && x.length <= 40))].slice(0, 200);
    const item: CatalogPoolItem = { id, ref: detail.ref, kind: e.kind, q: e.quality.score, rank: Math.round((s / top) * 1000) / 1000, words, row, detail: g.content };
    const size = JSON.stringify(item).length;
    if (chars + size > OFFER_CHAR_BUDGET - 8 * 1024) break; // room for the tool definitions
    chars += size;
    pool.push(item);
  }
  if (!pool.length) return null;
  return {
    v: CATALOG_OFFER_VERSION, game: i.game,
    tools: CATALOG_TOOLS.map((t) => ({ name: t.name, description: t.description, input_schema: t.input_schema })),
    resultCharBudget: RESULT_CHAR_BUDGET, searchLimitMax: SEARCH_LIMIT_MAX, pool,
  };
}

/** What a finished build reports (services/modbuilder/catalog.js) -> valid ModSpec asset slots only. */
export function librarySlotsFromService(raw: unknown): AssetSlot[] {
  if (!Array.isArray(raw)) return [];
  const out: AssetSlot[] = [];
  const ids = new Set<string>();
  for (const s of raw.slice(0, PICKS_MAX)) {
    if (!s || typeof s !== "object") continue;
    const o = s as Record<string, unknown>;
    const id = typeof o.id === "string" ? o.id : "";
    const kind = o.kind as AssetSlot["kind"];
    const purpose = typeof o.purpose === "string" ? o.purpose.trim() : "";
    const ref = typeof o.libraryRef === "string" ? o.libraryRef : "";
    if (!SLOT_ID_RE.test(id) || ids.has(id) || !(ASSET_KINDS as readonly string[]).includes(kind) || purpose.length < 3 || purpose.length > 300 || !LIBRARY_REF_RE.test(ref)) continue;
    ids.add(id);
    out.push({ id, kind, purpose, source: "library", libraryRef: ref, requirementIds: [] });
  }
  return out;
}
