// Cyrus R42: VANILLA REFERENCE entries for the catalog tools (metadata only, legal class game-derived). Built from the
// distilled index (lib/cyrus/versions/vanilla): what vanilla Minecraft has (items, blocks, sound events, entities,
// particles) with names, sizes and tags, so catalog_search can answer "which vanilla item looks like X / which
// vanilla sound fits" for the model. There are NO files behind these rows: status "reference", never library-eligible,
// never servable, never a ModSpec library slot (their ids are `v:...`, which CATALOG_REF_RE refuses). A pick is
// used BY ID (Material.DIAMOND_SWORD, the sound key minecraft:entity.zombie.hurt), never by copying Mojang's file.
// They are kept OUT of CatalogEntry on purpose: catalog entries forbid game-derived content (entry.ts).
import { vanillaIndex, vanillaModel, vanillaTexture } from "../../versions/vanilla";
import { vanillaIds } from "../../datapack/versions";

export const VANILLA_REF_VERSION = "26.1.2";
export const VANILLA_REF_ID_RE = /^v:(item|block|sound|entity|particle):[a-z0-9_./-]{1,96}$/;
export type VanillaRefKind = "item" | "block" | "sound" | "entity" | "particle";
export type VanillaRefEntry = {
  id: string; kind: VanillaRefKind; name: string; version: string; tags: string[];
  status: "reference"; legalClass: "game-derived"; libraryEligible: false; servable: false;
  /** size facts: texture px for items/blocks, variant count for sounds */
  size: { px?: string; files?: number } | null;
  facts: Record<string, unknown>;
};

// a few situation words per id fragment, so "weapon" finds swords and "ore" finds ores (kept small and literal)
const SYN: Record<string, string[]> = {
  sword: ["weapon", "blade", "melee"], axe: ["weapon", "tool"], pickaxe: ["tool", "mining"], shovel: ["tool", "digging"], hoe: ["tool", "farming"],
  bow: ["weapon", "ranged"], crossbow: ["weapon", "ranged"], trident: ["weapon", "ranged"], spear: ["weapon", "melee"], mace: ["weapon", "melee"],
  helmet: ["armor", "armour"], chestplate: ["armor", "armour"], leggings: ["armor", "armour"], boots: ["armor", "armour"],
  ore: ["mineral", "mining"], ingot: ["metal", "material"], nugget: ["metal"], gem: ["jewel"], diamond: ["gem", "jewel"], emerald: ["gem", "jewel"],
  potion: ["drink", "magic"], apple: ["food", "fruit"], bread: ["food"], stew: ["food"], fish: ["food"], cooked: ["food"],
  hurt: ["damage", "pain"], death: ["die", "dies"], ambient: ["idle"], step: ["footstep", "walk"], shoot: ["fire"], explode: ["explosion", "boom"],
  log: ["wood", "tree"], planks: ["wood"], leaves: ["tree", "foliage"], glass: ["window"], wool: ["cloth"], stone: ["rock"],
};
const words = (s: string) => s.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 1);
const tagsOf = (id: string, extra: string[] = []) => [...new Set([...words(id), ...words(id).flatMap((w) => SYN[w] ?? []), ...extra])].slice(0, 16);

let cache: VanillaRefEntry[] | null = null;
/** All reference entries for the indexed version (cached; ~4.8k rows of plain facts). [] when not indexed. */
export function vanillaRefEntries(): VanillaRefEntry[] {
  if (cache) return cache;
  const v = VANILLA_REF_VERSION, ix = vanillaIndex(v);
  if (!ix) return (cache = []);
  const base = { version: v, status: "reference" as const, legalClass: "game-derived" as const, libraryEligible: false as const, servable: false as const };
  const out: VanillaRefEntry[] = [];
  for (const id of ix.registries.itemDefinitions) {
    const tex = vanillaTexture(v, `item/${id}`) ?? vanillaTexture(v, `block/${id}`);
    const m = vanillaModel(v, `item/${id}`);
    out.push({ ...base, id: `v:item:${id}`, kind: "item", name: id.replace(/_/g, " "), tags: tagsOf(id, ["item"]), size: tex ? { px: `${tex.width}x${tex.height}` } : null,
      facts: { material: id.toUpperCase(), model: m?.p ?? null, texture: tex ? `minecraft:${tex.path}` : null, ...(tex?.animated ? { animated: true } : {}) } });
  }
  for (const id of ix.registries.blockstates) {
    const tex = vanillaTexture(v, `block/${id}`);
    out.push({ ...base, id: `v:block:${id}`, kind: "block", name: id.replace(/_/g, " "), tags: tagsOf(id, ["block"]), size: tex ? { px: `${tex.width}x${tex.height}` } : null,
      facts: { material: id.toUpperCase(), texture: tex ? `minecraft:${tex.path}` : null, ...(tex?.animated ? { animated: true } : {}) } });
  }
  for (const [ev, row] of Object.entries(ix.sounds.events)) {
    out.push({ ...base, id: `v:sound:${ev}`, kind: "sound", name: ev.replace(/[._]/g, " "), tags: tagsOf(ev, ["sound"]), size: { files: row.s.length },
      facts: { key: `minecraft:${ev}`, subtitle: row.sub ?? null, variants: row.s.length, how: row.s.length > 1 ? "add variants (replace: false) or swap all (replace: true) in the mod's sounds.json" : "swap with replace: true in the mod's sounds.json" } });
  }
  for (const id of vanillaIds("entity_type", v)) out.push({ ...base, id: `v:entity:${id}`, kind: "entity", name: id.replace(/_/g, " "), tags: tagsOf(id, ["mob", "entity"]), size: null, facts: { entityType: id.toUpperCase() } });
  for (const id of vanillaIds("particle_type", v)) out.push({ ...base, id: `v:particle:${id}`, kind: "particle", name: id.replace(/_/g, " "), tags: tagsOf(id, ["particle", "effect"]), size: null, facts: { particle: id.toUpperCase() } });
  return (cache = out);
}

/** Ranked reference rows for a query (token overlap on name + tags). */
export function searchVanillaRefs(query: string, opts: { kind?: VanillaRefKind | null; limit?: number } = {}): VanillaRefEntry[] {
  const q = [...new Set(words(query))];
  if (!q.length) return [];
  const scored: { e: VanillaRefEntry; s: number }[] = [];
  for (const e of vanillaRefEntries()) {
    if (opts.kind && e.kind !== opts.kind) continue;
    const nameW = words(e.name);
    let s = 0;
    for (const w of q) { if (nameW.includes(w)) s += 3; else if (e.tags.includes(w)) s += 1; }
    if (!s) continue;
    s -= Math.max(0, nameW.length - q.length) * 0.2; // prefer the plain item over long variants
    scored.push({ e, s });
  }
  return scored.sort((a, b) => b.s - a.s || a.e.id.localeCompare(b.e.id)).slice(0, Math.max(1, Math.min(8, opts.limit ?? 3))).map((x) => x.e);
}

export function getVanillaRef(id: string): VanillaRefEntry | null {
  if (!VANILLA_REF_ID_RE.test(id)) return null;
  return vanillaRefEntries().find((e) => e.id === id) ?? null;
}

/** The compact row catalog_search shows (~30 tokens). */
export const vanillaRow = (e: VanillaRefEntry) => ({ id: e.id, t: e.name, k: `vanilla-${e.kind}`, ...(e.size?.px ? { px: e.size.px } : {}), ...(e.size?.files ? { files: e.size.files } : {}) });
/** What catalog_get answers for a reference id. */
export const vanillaDetail = (e: VanillaRefEntry) => ({
  id: e.id, t: e.name, k: `vanilla-${e.kind}`, version: e.version, status: e.status, tags: e.tags.slice(0, 8), facts: e.facts, ...(e.size ? { size: e.size } : {}),
  rule: "vanilla reference: use it BY ID in the plugin/pack (Material, sound key, particle); no file is offered and none may be copied into the mod; it is not a library slot",
});

