// Cyrus R42: GAME-DERIVED assets (Minecraft vanilla files) in the studios. Pure + client-safe: the switches, the
// legal rules and the notice texts. Server checks live in ./foundation.server.ts and ./byo.server.ts.
//
// Two ways a vanilla file can reach a project, both legal class "game-derived" (lib/cyrus/assets3d/ledger.ts):
//  - BRING YOUR OWN (CYRUS_BYO_GAME_ASSETS=1): the customer picks files from THEIR OWN Minecraft install / jar in the
//    browser; the browser hashes them; the server re-hashes and verifies each against the private vanilla reference
//    (CYRUS_VANILLA_REFERENCE_DIR) and keeps it project-private with retention "job". Fail closed: no reference,
//    no flag or production without upload storage = refused.
//  - DEV FOUNDATION (CYRUS_DEV_FOUNDATION=1 + CYRUS_DEV_FOUNDATION_DIR, never production): the owner's copy of the
//    vanilla files on the dev host, for TESTING the "build on a vanilla base" flow. Preview (owner) accounts only.
// Either way: never library-eligible, never contributed, never shared, and EXPORT is delta-only (an unchanged
// vanilla file is flagged out of every pack: ./delta.ts + lib/cyrus/textures/pack.ts).

export const BYO_FLAG = "CYRUS_BYO_GAME_ASSETS";
export const DEV_FOUNDATION_FLAG = "CYRUS_DEV_FOUNDATION";
export const DEV_FOUNDATION_DIR_ENV = "CYRUS_DEV_FOUNDATION_DIR";
/** retention "job": a BYO file and what is derived from it are usable for this long, then refused (and swept). */
export const BYO_RETENTION_MS = 7 * 24 * 3600_000;

export type GameSource = "byo" | "dev-foundation";
/** Stamped on every texture doc / sound row derived from a game file (lib/cyrus/studios/paint.ts TextureDoc.base). */
export type GameBase = {
  legal: "game-derived";
  source: GameSource;
  /** sha256 of the original file bytes (the user's file or the dev store's) */
  sha256: string;
  /** sha256 of the base's RGBA pixels (textures): equal to the result's = unchanged, so it is never packed */
  pixelSha256?: string;
  /** "26.1.2 assets/minecraft/textures/item/stick.png" when verified against the reference; null = unverified set */
  vanilla: string | null;
  /** the dev store's set (dev-foundation only), e.g. vanilla-26.1.2 / mc-items-unknown */
  set?: string;
  /** ISO time after which this content is refused (BYO retention "job"); absent = dev store (project, dev only) */
  expiresAt?: string;
};

export const byoOn = (env: Record<string, string | undefined> = process.env) => env[BYO_FLAG] === "1";

/** The customer-facing notice shown before anything is read (Texture + Sound studios). */
export const BYO_NOTICE = [
  "Use your own Minecraft files as a starting point. Pick textures, sounds or models from your own Minecraft install or game jar.",
  "Your browser reads them; Nxeon checks each one is an unchanged vanilla Minecraft file and keeps it only inside this project, for this job (7 days).",
  "These files belong to Mojang. They are never added to the community library, never shared and never sent to anyone else.",
  "When you export or build, only what you CHANGED ships (your retexture or new sound). Unchanged Minecraft files are left out of the pack.",
] as const;
export const DEV_FOUNDATION_NOTICE = "DEV FOUNDATION (testing only): vanilla files from the owner's reference copy on the dev host. Game-derived: never shipped unchanged, never in the library, never in production.";

/** Is a base still usable at `now`? (retention "job"). */
export const baseLive = (b: GameBase | null | undefined, now = Date.now()) => !b || !b.expiresAt || Date.parse(b.expiresAt) > now;

const SHA = /^[0-9a-f]{64}$/;
/** Validate a GameBase from untrusted JSON (null = invalid). */
export function checkGameBase(raw: unknown): GameBase | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as Record<string, unknown>;
  if (r.legal !== "game-derived" || (r.source !== "byo" && r.source !== "dev-foundation") || typeof r.sha256 !== "string" || !SHA.test(r.sha256)) return null;
  if (r.pixelSha256 !== undefined && (typeof r.pixelSha256 !== "string" || !SHA.test(r.pixelSha256))) return null;
  if (r.vanilla !== null && (typeof r.vanilla !== "string" || r.vanilla.length > 200)) return null;
  if (r.set !== undefined && (typeof r.set !== "string" || !/^[a-z0-9.-]{1,40}$/.test(r.set))) return null;
  if (r.expiresAt !== undefined && (typeof r.expiresAt !== "string" || Number.isNaN(Date.parse(r.expiresAt)))) return null;
  const extra = Object.keys(r).filter((k) => !["legal", "source", "sha256", "pixelSha256", "vanilla", "set", "expiresAt"].includes(k));
  if (extra.length) return null;
  return { legal: "game-derived", source: r.source, sha256: r.sha256, ...(r.pixelSha256 ? { pixelSha256: r.pixelSha256 as string } : {}), vanilla: (r.vanilla as string | null) ?? null, ...(r.set ? { set: r.set as string } : {}), ...(r.expiresAt ? { expiresAt: r.expiresAt as string } : {}) };
}

