// Delta-only export for game-derived content (pure). A retexture ships the CHANGED texture; a file whose pixels (or
// bytes) are still the vanilla base is flagged OUT of the pack, never shipped. Used by lib/cyrus/textures/pack.ts.
import { createHash } from "node:crypto";
import type { Raster } from "../textures/render";
import { baseLive, type GameBase } from "./policy";

export const pixelSha256 = (r: Raster) => createHash("sha256").update(Buffer.from(r.px.buffer, r.px.byteOffset, r.px.byteLength)).digest("hex");

export type DeltaDecision = { ship: true } | { ship: false; reason: string };

/** Ship a game-derived texture only if it is still live (retention) and its pixels differ from its base. */
export function deltaTexture(base: GameBase | null | undefined, result: Raster, now = Date.now()): DeltaDecision {
  if (!base) return { ship: true };
  if (!baseLive(base, now)) return { ship: false, reason: "built on your own Minecraft file, which is kept only for 7 days; import it again to keep working on it" };
  if (!base.pixelSha256) return { ship: false, reason: "built on a Minecraft file without a pixel record, so Nxeon cannot prove it changed (left out)" };
  if (pixelSha256(result) === base.pixelSha256) return { ship: false, reason: "unchanged vanilla Minecraft texture: only changed files ship (delta-only)" };
  return { ship: true };
}

/** Byte-level rule for any other file (sounds, models): identical to the base or to any known vanilla file = left out. */
export function deltaFile(bytesSha256: string, base: GameBase | null | undefined, isVanillaSha?: (sha: string) => boolean): DeltaDecision {
  if (base && bytesSha256 === base.sha256) return { ship: false, reason: "unchanged Minecraft file: only changed files ship (delta-only)" };
  if (isVanillaSha?.(bytesSha256)) return { ship: false, reason: "this is an unchanged vanilla Minecraft file: it is never packed" };
  return { ship: true };
}

