// Cyrus R42 DEV FOUNDATION store (SERVER ONLY, TESTING ONLY). The owner's vanilla files, content-addressed, on the
// dev host (/tank/cyrus-library-staging/_reference/foundation on the primary, a copy on node-2). Never in git, never
// in production. Built by _reference/tools/foundation_build.py:  <dir>/index.json + <dir>/files/<aa>/<sha256>.
// Fail closed, every call: the flag CYRUS_DEV_FOUNDATION=1 AND CYRUS_DEV_FOUNDATION_DIR AND NODE_ENV !== production
// AND the dir is not inside the production tree; anything else = { ok: false } and no file is ever read.
import { createHash } from "node:crypto";
import { existsSync, readFileSync, realpathSync } from "node:fs";
import { join, resolve } from "node:path";
import { DEV_FOUNDATION_DIR_ENV, DEV_FOUNDATION_FLAG } from "./policy";

export type FoundationSet = { id: string; label: string; provenance: "mojang-vanilla" | "mojang-vanilla-unverified-version" | "unknown"; version: string | null; verified: boolean; entries: number };
export type FoundationEntry = {
  sha256: string; set: string; path: string; kind: "texture" | "sound" | "model"; name: string; bytes: number; tags: string[];
  w?: number; h?: number; animated?: boolean; unreadable?: boolean; vanilla?: { version: string; path: string };
};
export type Foundation = { dir: string; sets: FoundationSet[]; entries: FoundationEntry[]; bySha: Map<string, FoundationEntry[]> };
export type FoundationGate = { ok: true; dir: string } | { ok: false; reason: string };

const PROD_TREES = ["/opt/nxeon", "/opt/nxeon-staging"];
const SHA = /^[0-9a-f]{64}$/;

export function foundationGate(env: Record<string, string | undefined> = process.env): FoundationGate {
  if (env[DEV_FOUNDATION_FLAG] !== "1") return { ok: false, reason: "the dev foundation store is off (CYRUS_DEV_FOUNDATION)" };
  if (env.NODE_ENV === "production") return { ok: false, reason: "the dev foundation store never runs in production" };
  const raw = env[DEV_FOUNDATION_DIR_ENV];
  if (!raw) return { ok: false, reason: `${DEV_FOUNDATION_DIR_ENV} is not set` };
  let dir: string;
  try { dir = realpathSync(resolve(raw)); } catch { return { ok: false, reason: "the dev foundation directory does not exist" }; }
  if (PROD_TREES.some((p) => dir === p || dir.startsWith(p + "/"))) return { ok: false, reason: "the dev foundation directory is inside a production tree" };
  if (!existsSync(join(dir, "index.json"))) return { ok: false, reason: "the dev foundation directory has no index.json" };
  return { ok: true, dir };
}

const cache = new Map<string, Foundation>();
/** The store, or null when the gate refuses (callers answer 404/403 and never read a file). */
export function loadFoundation(env: Record<string, string | undefined> = process.env): Foundation | null {
  const g = foundationGate(env);
  if (!g.ok) return null;
  const hit = cache.get(g.dir);
  if (hit) return hit;
  try {
    const idx = JSON.parse(readFileSync(join(g.dir, "index.json"), "utf8")) as { schema: number; sets: FoundationSet[]; entries: FoundationEntry[] };
    if (idx.schema !== 1 || !Array.isArray(idx.entries)) return null;
    const entries = idx.entries.filter((e) => SHA.test(e.sha256) && ["texture", "sound", "model"].includes(e.kind));
    const bySha = new Map<string, FoundationEntry[]>();
    for (const e of entries) bySha.set(e.sha256, [...(bySha.get(e.sha256) ?? []), e]);
    const f: Foundation = { dir: g.dir, sets: idx.sets, entries, bySha };
    cache.set(g.dir, f);
    return f;
  } catch { return null; }
}
export const _resetFoundationCache = () => cache.clear();

/** The bytes of one entry, re-verified against its sha256 on every read (a tampered file is refused). */
export function readFoundationFile(f: Foundation, sha256: string): Buffer | null {
  if (!SHA.test(sha256) || !f.bySha.has(sha256)) return null;
  try {
    const b = readFileSync(join(f.dir, "files", sha256.slice(0, 2), sha256));
    return createHash("sha256").update(b).digest("hex") === sha256 ? b : null;
  } catch { return null; }
}

export const setOf = (f: Foundation, id: string) => f.sets.find((s) => s.id === id) ?? null;

const words = (s: string) => s.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 1);
/** Ranked entries for a query (name + tags). Item textures first among equals (most foundations are item retextures). */
export function searchFoundation(f: Foundation, query: string, opts: { kind?: FoundationEntry["kind"] | null; set?: string | null; limit?: number; offset?: number } = {}): { total: number; items: FoundationEntry[] } {
  const q = [...new Set(words(query))];
  const scored: { e: FoundationEntry; s: number }[] = [];
  for (const e of f.entries) {
    if (opts.kind && e.kind !== opts.kind) continue;
    if (opts.set && e.set !== opts.set) continue;
    let s = 0;
    if (q.length) {
      const nw = words(e.name);
      for (const w of q) { if (nw.includes(w)) s += 3; else if (e.tags.includes(w)) s += 1; else if (e.path.toLowerCase().includes(w)) s += 0.5; }
      if (!s) continue;
      s -= Math.max(0, nw.length - q.length) * 0.2;
    }
    if (e.path.includes("textures/item/")) s += 0.3;
    if (e.set === "vanilla-26.1.2") s += 0.2;
    scored.push({ e, s });
  }
  scored.sort((a, b) => b.s - a.s || a.e.path.localeCompare(b.e.path));
  const off = Math.max(0, opts.offset ?? 0), lim = Math.max(1, Math.min(60, opts.limit ?? 24));
  return { total: scored.length, items: scored.slice(off, off + lim).map((x) => x.e) };
}

