// Cyrus R42: start a project texture FROM A GAME FILE (BYO import or dev foundation). SERVER ONLY. The bytes are
// decoded with the bounded PNG decoder, normalised to an editable studio doc (first animation frame, binary alpha,
// 128 px icons halved to 64), stamped with a server-side GameBase (legal class game-derived) and saved through the
// normal Texture Studio save (plan gate "create", project ownership, quality bar, revision). Never contributed.
import { createHash } from "node:crypto";
import { decodePng } from "../library/png-decode";
import type { Raster } from "../textures/render";
import { docFromRaster, renderDoc } from "../studios/paint";
import { saveTexture, StudioError, type SaveResult, type StudioServiceDeps } from "../studios/service";
import { pixelSha256 } from "./delta";
import { BYO_RETENTION_MS, type GameBase, type GameSource } from "./policy";

export const GAME_PNG_LIMITS = { maxBytes: 512 * 1024, sizes: [16, 32, 64, 128] as const, maxChunks: 64, anySize: { maxSide: 1024, maxPixels: 1024 * 64 } };
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

export type Normalised = { raster: Raster; notes: string[] };
/** A game PNG -> a square 16/32/64 raster the studio can edit (pure apart from decoding). */
export function normaliseGamePng(bytes: Buffer): Normalised | { error: string } {
  const d = decodePng(bytes, GAME_PNG_LIMITS);
  if (!d.ok) return { error: d.error };
  const notes: string[] = [];
  let { width: w, height: h } = d;
  let px = d.raster.px;
  // a vertical animation strip: keep the first frame
  if (h > w && h % w === 0) { px = px.slice(0, w * w * 4); notes.push(`animation strip: the first of ${h / w} frames`); h = w; }
  if (w !== h) return { error: `the texture is ${w}x${h}; the studio edits square 16, 32 or 64 px textures` };
  let size = w;
  while (size > 64 && size % 2 === 0) { // icons: halve (nearest) until it fits
    const n = size / 2, out = new Uint8ClampedArray(n * n * 4);
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { const s = ((y * 2) * size + x * 2) * 4, t = (y * n + x) * 4; out[t] = px[s]; out[t + 1] = px[s + 1]; out[t + 2] = px[s + 2]; out[t + 3] = px[s + 3]; }
    px = out; notes.push(`scaled ${size} px to ${n} px`); size = n;
  }
  if (![16, 32, 64].includes(size)) return { error: `the texture is ${size} px; the studio edits 16, 32 or 64 px textures` };
  let soft = 0;
  for (let i = 3; i < px.length; i += 4) if (px[i] !== 0 && px[i] !== 255) { soft++; px[i] = px[i] >= 128 ? 255 : 0; }
  for (let i = 0; i < px.length; i += 4) if (px[i + 3] === 0) px[i] = px[i + 1] = px[i + 2] = 0;
  if (soft) notes.push(`${soft} semi-transparent pixels made solid or clear (the studio paints opaque pixels)`);
  return { raster: { size, px }, notes };
}

