    legal: "game-derived", source: i.source, sha256: sha(i.bytes), pixelSha256: pixelSha256(renderDoc(d.doc)), vanilla: i.vanilla,
    ...(i.set ? { set: i.set } : {}), ...(i.source === "byo" ? { expiresAt: new Date((i.now ?? Date.now()) + BYO_RETENTION_MS).toISOString() } : {}),
  };
  const r = await saveTexture(deps, {
    userId: i.userId, projectId: i.projectId, key: i.key, doc: d.doc, baseAssetId: null, expectedHeadId: i.expectedHeadId, origin: "imported", gameBase: base,
    message: `Started ${i.key} from ${i.vanilla ? `vanilla ${i.vanilla.split(" ")[0]} ${i.vanilla.split("/").pop()}` : `a Minecraft file (${i.set ?? "unverified"})`} (game-derived)`,
    provenance: { gameFile: { source: i.source, sha256: base.sha256, vanilla: i.vanilla, set: i.set ?? null, notes: n.notes } },
