// Cyrus R42: HTTP handlers of /api/cyrus/assets/v1/game-assets/** (framework-free, tested with fakes). Every handler
// goes through the studio `run` (studio viewer or 404, rate limit, error mapping), then its own switch, server side:
//   BYO (bring your own game files)  CYRUS_BYO_GAME_ASSETS=1 + the private vanilla reference, else 404 / 503 (fail closed)
//   DEV FOUNDATION                   foundationGate (flag + dir + not production) AND a preview (owner) viewer, else 404
import { BYO_NOTICE, byoOn, DEV_FOUNDATION_NOTICE } from "./policy";
import type { Foundation } from "./foundation.server";
import { readFoundationFile, searchFoundation, setOf } from "./foundation.server";
import { textureFromGameFile } from "./service";
import { lookupVanillaSha, type VanillaReference } from "../versions/vanilla/reference.server";
import { suggestVanillaSounds } from "../versions/vanilla/validate";
import { json, need, readJson, RE, run, NOT_FOUND, NO_STORE, type StudioApiDeps } from "../studios/http";
import { StudioError } from "../studios/service";
import { createHash } from "node:crypto";

export type GameAssetDeps = {
  env: Record<string, string | undefined>;
  reference: () => VanillaReference | null;
  foundation: () => Foundation | null;
};
const SHA = /^[0-9a-f]{64}$/;
const MAX_FILE = 512 * 1024;
const VERIFY_MAX = 500;
const PATH_RE = /^[A-Za-z0-9 _./()'+-]{1,200}$/;

/** GET /game-assets: what this viewer may do (the studios show the import / foundation panels from this). */
export const handleGameAssetCaps = (_req: Request, deps: StudioApiDeps, g: GameAssetDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  const ref = byoOn(g.env) ? g.reference() : null;
  const f = viewer.preview ? g.foundation() : null;
  return json(200, {
    byo: byoOn(g.env) ? { on: !!ref, reason: ref ? null : "verification is not available on this server yet", notice: BYO_NOTICE, versions: ref?.versions ?? [] } : { on: false, reason: "off", notice: BYO_NOTICE, versions: [] },
    foundation: f ? { on: true, notice: DEV_FOUNDATION_NOTICE, sets: f.sets } : { on: false },
  });
});

/** POST /game-assets/verify { files: [{ path, sha256 }] }: which are unchanged vanilla files (no bytes sent). */
export const handleByoVerify = (req: Request, deps: StudioApiDeps, g: GameAssetDeps) => run(deps, { key: "byo-verify", max: 30 }, async () => {
  if (!byoOn(g.env)) return NOT_FOUND();
  const ref = g.reference();
  if (!ref) return json(503, { error: "Nxeon cannot verify Minecraft files on this server yet, so nothing was imported.", code: "no_reference" });
  const b = await readJson(req);
  const files = Array.isArray(b.files) ? b.files.slice(0, VERIFY_MAX) : [];
  need(files.length > 0, "send files: [{ path, sha256 }]");
  const out = files.map((f) => {
    const o = (f ?? {}) as { path?: unknown; sha256?: unknown };
    const path = typeof o.path === "string" ? o.path.slice(0, 200) : "", sha = typeof o.sha256 === "string" ? o.sha256 : "";
    if (!SHA.test(sha)) return { path, sha256: sha, vanilla: null, ok: false, why: "bad hash" };
    const hits = lookupVanillaSha(ref, sha);
    return hits.length ? { path, sha256: sha, ok: true, vanilla: `${hits[0].version} ${hits[0].path}`, kind: kindOf(hits[0].path), ...(hits[0].path.includes("/sounds/") ? { events: soundEventsFor(hits[0].path, hits[0].version) } : {}) }
      : { path, sha256: sha, vanilla: null, ok: false, why: "not an unchanged vanilla Minecraft file (edited, from a mod, or a version Nxeon does not know)" };
  });
  return json(200, { files: out, verified: out.filter((x) => x.ok).length });
});

/** POST /game-assets/import { projectId, key, name, dataBase64, expectedHeadId }: start a texture from the user's own vanilla PNG. */
export const handleByoImport = (req: Request, deps: StudioApiDeps, g: GameAssetDeps) => run(deps, { key: "byo-import", max: 20 }, async ({ viewer }) => {
  if (!byoOn(g.env)) return NOT_FOUND();
  const ref = g.reference();
  if (!ref) return json(503, { error: "Nxeon cannot verify Minecraft files on this server yet, so nothing was imported.", code: "no_reference" });
  const b = await readJson(req);
  const projectId = String(b.projectId ?? ""), key = String(b.key ?? "");
  need(RE.project.test(projectId), "projectId is not valid"); need(RE.key.test(key), "key must be 2-32 lowercase letters, digits and underscores");
  const bytes = typeof b.dataBase64 === "string" ? Buffer.from(b.dataBase64, "base64") : Buffer.alloc(0);
  need(bytes.length > 0 && bytes.length <= MAX_FILE, "dataBase64 must be the file (at most 512 KB)");
  const sha = createHash("sha256").update(bytes).digest("hex");
  // the SERVER hash decides; what the browser claimed is never trusted
  const hits = lookupVanillaSha(ref, sha).filter((h) => h.path.startsWith("assets/minecraft/textures/") && h.path.endsWith(".png"));
  if (!hits.length) throw new StudioError(422, "not_vanilla", "This file is not an unchanged vanilla Minecraft texture, so it cannot be imported this way. Upload your own art with Upload instead.");
  const r = await textureFromGameFile(deps.service, { userId: viewer.userId, projectId, key, expectedHeadId: typeof b.expectedHeadId === "string" ? b.expectedHeadId : null, bytes, source: "byo", vanilla: `${hits[0].version} ${hits[0].path}` });
  return json(200, r);
});

/** GET /game-assets/foundation?q=&kind=&set=&offset=: DEV ONLY, preview (owner) viewers only. Metadata, never bytes. */
export const handleFoundationList = (req: Request, deps: StudioApiDeps, g: GameAssetDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  if (!viewer.preview) return NOT_FOUND();
  const f = g.foundation();
  if (!f) return NOT_FOUND();
  const u = new URL(req.url).searchParams;
  const kind = u.get("kind");
  const r = searchFoundation(f, (u.get("q") ?? "").slice(0, 80), { kind: kind === "texture" || kind === "sound" || kind === "model" ? kind : null, set: u.get("set"), offset: Number(u.get("offset") ?? 0) || 0, limit: 36 });
  return json(200, {
    notice: DEV_FOUNDATION_NOTICE, total: r.total, sets: f.sets,
    items: r.items.map((e) => ({ ...e, status: "dev-foundation", legalClass: "game-derived", libraryEligible: false, provenance: setOf(f, e.set)?.provenance ?? "unknown", ...(e.kind === "sound" ? { events: soundEventsFor(e.path, "26.1.2") } : {}) })),
  });
});

/** GET /game-assets/foundation/<sha256>: the bytes, DEV ONLY, preview viewers only (studio thumbnails / audition). */
export const handleFoundationFile = (_req: Request, deps: StudioApiDeps, g: GameAssetDeps, sha: string) => run(deps, { key: "read", max: 600 }, async ({ viewer }) => {
  if (!viewer.preview || !SHA.test(sha)) return NOT_FOUND();
  const f = g.foundation();
  if (!f) return NOT_FOUND();
  const e = f.bySha.get(sha)?.[0];
  const b = e ? readFoundationFile(f, sha) : null;
  if (!e || !b) return NOT_FOUND();
  const type = e.kind === "sound" ? "audio/ogg" : e.kind === "model" ? "application/json" : "image/png";
  return new Response(new Uint8Array(b), { status: 200, headers: { ...NO_STORE, "content-type": type, "x-cyrus-legal": "game-derived; dev-foundation; not for redistribution" } });
});

/** POST /game-assets/foundation/use { projectId, sha256, key, expectedHeadId }: a project texture built on a foundation file. */
export const handleFoundationUse = (req: Request, deps: StudioApiDeps, g: GameAssetDeps) => run(deps, { key: "foundation-use", max: 30 }, async ({ viewer }) => {
  if (!viewer.preview) return NOT_FOUND();
  const f = g.foundation();
  if (!f) return NOT_FOUND();
  const b = await readJson(req);
  const projectId = String(b.projectId ?? ""), key = String(b.key ?? ""), sha = String(b.sha256 ?? "");
  need(RE.project.test(projectId), "projectId is not valid"); need(RE.key.test(key), "key must be 2-32 lowercase letters, digits and underscores"); need(SHA.test(sha), "sha256 is not valid");
  const e = f.bySha.get(sha)?.[0];
  if (!e) return NOT_FOUND();
  if (e.kind !== "texture") throw new StudioError(422, "not_a_texture", e.kind === "sound" ? "Sounds are used as a foundation from the Sound Studio (audition + replace/extend a vanilla event)." : "Models are reference only for now.");
  const bytes = readFoundationFile(f, sha);
  if (!bytes) return NOT_FOUND();
  const r = await textureFromGameFile(deps.service, { userId: viewer.userId, projectId, key, expectedHeadId: typeof b.expectedHeadId === "string" ? b.expectedHeadId : null, bytes, source: "dev-foundation", vanilla: e.vanilla ? `${e.vanilla.version} ${e.vanilla.path}` : null, set: e.set });
  return json(200, r);
});

const kindOf = (p: string) => (p.endsWith(".ogg") ? "sound" : p.endsWith(".json") ? "model" : "texture");
/** The vanilla events that play a sound file (assets/minecraft/sounds/mob/zombie/hurt1.ogg -> entity.zombie.hurt). */
function soundEventsFor(path: string, version: string): { event: string; how: string }[] {
  const name = path.replace(/^assets\/minecraft\/sounds\//, "").replace(/\.ogg$/, "");
  const hits = suggestVanillaSounds(version, name.replace(/[0-9]+$/, "").replace(/\//g, " "), { limit: 3 });
  return hits.map((h) => ({ event: h.event, how: h.how }));
}

