132:function publicFacts(rec) {

const POOL_ID_RE = /^c:[0-9a-f]{12,64}$/;
const REF_RE = /^cat:[0-9a-f]{64}$/;
const SLOT_ID_RE = /^[a-z][a-z0-9_]{0,47}$/;
const SLOT_KINDS = ["texture", "sound", "model", "ui"];
const CATALOG_KINDS = ["model", "texture-set", "texture", "sprite", "hdri", "decal", "sound", "music"];
const gateKindOf = (k) => (k === "sound" || k === "music" ? "sound" : k === "model" ? "model" : "texture");

/** POST /builds `catalog` field -> null (absent) | { error } | the normalized offer. */
function parseCatalogOffer(raw) {
  if (raw == null) return null;
  const bad = (m) => ({ error: `catalog: ${m}` });
  if (typeof raw !== "object" || Array.isArray(raw)) return bad("must be an object");
  let size = 0;
  try { size = JSON.stringify(raw).length; } catch { return bad("not serializable"); }
  if (size > MAX_OFFER_CHARS) return bad("offer too large");
  if (typeof raw.v !== "string" || !/^cat-offer-\d+$/.test(raw.v)) return bad("unknown offer version");
  if (!Array.isArray(raw.tools) || raw.tools.length !== TOOL_NAMES.length) return bad("tools must be catalog_search + catalog_get");
  const tools = [];
  for (const t of raw.tools) {
    if (!t || !TOOL_NAMES.includes(t.name) || typeof t.description !== "string" || t.description.length > 1200 || !t.input_schema || typeof t.input_schema !== "object") return bad("bad tool definition");
    tools.push({ name: t.name, description: t.description, input_schema: t.input_schema });
  }
  if (new Set(tools.map((t) => t.name)).size !== TOOL_NAMES.length) return bad("duplicate tool");
  if (!Array.isArray(raw.pool) || !raw.pool.length || raw.pool.length > MAX_POOL) return bad(`pool must hold 1-${MAX_POOL} assets`);
  const pool = [];
  const seen = new Set();
  for (const p of raw.pool) {
    if (!p || !POOL_ID_RE.test(String(p.id)) || !REF_RE.test(String(p.ref)) || !CATALOG_KINDS.includes(p.kind)) return bad("bad pool entry");
    if (seen.has(p.ref)) return bad("duplicate pool ref");
    seen.add(p.ref);
    if (!p.row || typeof p.row !== "object" || typeof p.detail !== "string" || !Array.isArray(p.words)) return bad("bad pool entry");
    pool.push({
      id: p.id, ref: p.ref, kind: p.kind, q: Math.max(0, Math.min(100, Number(p.q) || 0)), rank: Math.max(0, Math.min(1, Number(p.rank) || 0)),
      words: p.words.filter((w) => typeof w === "string" && /^[a-z0-9-]{1,40}$/.test(w)).slice(0, 200), row: p.row, detail: p.detail,
    });
  }
  const resultCharBudget = Number.isInteger(raw.resultCharBudget) ? Math.max(500, Math.min(8000, raw.resultCharBudget)) : 3800;
  const searchLimitMax = Number.isInteger(raw.searchLimitMax) ? Math.max(1, Math.min(8, raw.searchLimitMax)) : 8;
  const game = typeof raw.game === "string" && /^[a-z][a-z0-9-]{1,31}$/.test(raw.game) ? raw.game : null;
  return { v: raw.v, game, tools, pool, resultCharBudget, searchLimitMax, maxCalls: MAX_TOOL_CALLS };
}

const filesDir = (rec, workDir) => path.join(workDir, `${rec.id}-catalog`);

/** Extra CLI args for one AI call ([] without an offer). Writes the offer + MCP config outside the workspace. */
function collectPicks(ws, rec) {
  const f = path.join(ws, PICKS_FILE);
  if (!rec.catalog) return null; // no offer: the file (if any) is removed by sanitizeWorkspace like any unexpected file
  if (!fs.existsSync(f)) return null; // a repair round that did not touch it keeps the earlier picks
  let doc = null;
  try { doc = JSON.parse(fs.readFileSync(f, "utf8")); } catch { doc = null; }
  fs.rmSync(f, { force: true });
  const list = Array.isArray(doc) ? doc : doc && Array.isArray(doc.slots) ? doc.slots : null;
  const slots = [], dropped = [];
  if (!list) { rec.librarySlots = []; rec.libraryDropped = [{ id: null, reason: `${PICKS_FILE} is not {"slots":[...]}` }]; return rec.librarySlots; }
  const byRef = new Map(rec.catalog.pool.map((p) => [p.ref, p]));
  const ids = new Set();
  for (const s of list.slice(0, 50)) {
    const id = s && typeof s.id === "string" ? s.id : null;
    const why = !s || typeof s !== "object" ? "not an object"
      : !id || !SLOT_ID_RE.test(id) ? "bad id"
      : ids.has(id) ? "duplicate id"
      : !SLOT_KINDS.includes(s.kind) ? "kind must be texture, sound, model or ui"
      : typeof s.purpose !== "string" || s.purpose.trim().length < 3 || s.purpose.trim().length > 300 ? "purpose must be 3-300 characters"
      : typeof s.libraryRef !== "string" || !REF_RE.test(s.libraryRef) ? "libraryRef must be the cat:<sha256> ref"
      : !byRef.has(s.libraryRef) ? "not one of the catalog assets offered to this build"
      : !(gateKindOf(byRef.get(s.libraryRef).kind) === s.kind || (s.kind === "ui" && gateKindOf(byRef.get(s.libraryRef).kind) === "texture")) ? `the asset is a ${byRef.get(s.libraryRef).kind}, the slot is ${s.kind}`
      : slots.length >= MAX_PICKS ? `more than ${MAX_PICKS} picks`
      : null;
    if (why) { dropped.push({ id, reason: why }); continue; }
    ids.add(id);
    slots.push({ id, kind: s.kind, purpose: s.purpose.trim(), source: "library", libraryRef: s.libraryRef, requirementIds: [] });
  }
  rec.librarySlots = slots;
  rec.libraryDropped = dropped.slice(0, 20);
  return slots;
}

