/** The catalog-tool view of the store (lib/cyrus/library/v2/tools.ts FoundationTools). Textures only for now. */
export function foundationTools(f: Foundation): import("../library/v2/tools").FoundationTools {
  const prov = (set: string) => setOf(f, set)?.provenance ?? "unknown";
