    get: (sha) => { const e = f.bySha.get(sha)?.[0]; return e ? { sha256: e.sha256, name: e.name, kind: e.kind, set: e.set, provenance: prov(e.set), path: e.path, bytes: e.bytes, ...(e.w ? { w: e.w, h: e.h } : {}), ...(e.vanilla ? { vanilla: e.vanilla } : {}) } : null; },
  };
}

export type FoundationSlotDecision = { ok: true; entry: FoundationEntry; bytes: Buffer } | { ok: false; code: "not_foundation" | "off" | "not_found" | "kind_mismatch"; reason: string };
/** Re-check a ModSpec slot { source: "imported", foundationRef } against the dev store before any use. */
export function resolveFoundationSlot(slot: { id: string; kind: string; source: string; foundationRef?: string }, f: Foundation | null): FoundationSlotDecision {
  if (slot.source !== "imported" || !slot.foundationRef || !/^vf:[0-9a-f]{64}$/.test(slot.foundationRef)) return { ok: false, code: "not_foundation", reason: `slot ${slot.id} has no foundationRef` };
  if (!f) return { ok: false, code: "off", reason: "the dev foundation store is off here (never in production)" };
  const sha = slot.foundationRef.slice(3), e = f.bySha.get(sha)?.[0];
  if (!e) return { ok: false, code: "not_found", reason: `${slot.foundationRef} is not in the dev foundation store` };
  if ((slot.kind === "ui" ? "texture" : slot.kind) !== e.kind) return { ok: false, code: "kind_mismatch", reason: `slot ${slot.id} is ${slot.kind}, the file is a ${e.kind}` };
  const bytes = readFoundationFile(f, sha);
  return bytes ? { ok: true, entry: e, bytes } : { ok: false, code: "not_found", reason: "the foundation file failed its hash check" };
}
