// The host-facing switch for catalog tools in builds (SERVER-ONLY). lib/modbuilder/create.ts calls
// catalogOfferForBuild() after the asset gate; it returns the `catalog` field for the build service or null.
//   CYRUS_CATALOG_TOOLS=1           master switch (web process). Unset = null before any lookup (no DB, no index, no I/O).
//   CYRUS_CATALOG_INDEX=<file>      the catalog search index (SQLite FTS file built from catalog v2 entries, read here).
//                                   Unset/missing = null. A Postgres index (r26) replaces this provider later.
//   CYRUS_SOUND_LIBRARY_CLEARED=1   the owner's proprietary library may be offered (same clearance as the sound library).
// The build service must advertise features.catalogTools (image 0.6+); an older image is never sent the field.
// HOST SEAM: the plan lookup and the service-health probe are passed in by the caller (they are Nxeon code).
import { existsSync } from "node:fs";
import type { CatalogIndex } from "./retrieval";
import { buildCatalogOffer, type SvcCatalogOffer } from "./build-offer";

export const catalogToolsOn = (): boolean => process.env.CYRUS_CATALOG_TOOLS === "1";

let indexPromise: { file: string; p: Promise<CatalogIndex | null> } | null = null;
/** The configured index, opened once per process. Any failure = null (fail closed, never throws). */
export function configuredCatalogIndex(): Promise<CatalogIndex | null> {
  const file = process.env.CYRUS_CATALOG_INDEX || "";
  if (!file || !existsSync(file)) return Promise.resolve(null);
  if (indexPromise?.file !== file) {
    indexPromise = {
      file,
      p: import("./sqlite-index").then((m) => m.createSqliteCatalogIndex(file)).then(async (ix) => ((await ix.size()) > 0 ? ix : null)).catch(() => null),
    };
  }
  return indexPromise.p;
}

export type CatalogWiringDeps = {
  on?: () => boolean;
  index?: () => Promise<CatalogIndex | null>;
  /** the account's plan tier (any spelling asset-gate understands); throwing = unknown = nothing offered */
  tierOf: (userId: string) => Promise<string>;
  /** does the running build service understand `catalog`? (its /health features.catalogTools) */
  serviceSupports: () => Promise<boolean>;
  proprietaryCleared?: () => boolean;
};

export async function catalogOfferForBuild(i: { userId: string; text: string; game?: string }, deps: CatalogWiringDeps): Promise<SvcCatalogOffer | null> {
  if (!(deps.on ?? catalogToolsOn)()) return null;
  try {
    const index = await (deps.index ?? configuredCatalogIndex)();
    if (!index) return null;
    if (!(await deps.serviceSupports())) return null;
    const plan = await deps.tierOf(i.userId);
    return await buildCatalogOffer({ index, plan, game: i.game ?? "minecraft", proprietaryCleared: (deps.proprietaryCleared ?? (() => process.env.CYRUS_SOUND_LIBRARY_CLEARED === "1"))(), text: i.text });
  } catch (e) {
    console.error("[cyrus] catalog offer skipped", (e as Error).message);
    return null;
  }
}

