// ------------------------------------------------------------------------------------------------ in-memory studio
type Mem = { projects: Map<string, ProjectRow>; revs: (RevRow & { projectId: string })[]; assets: AssetRow[]; ids: Set<string> };
function memStore(): StudioStore & { mem: Mem } {
  const mem: Mem = { projects: new Map(), revs: [], assets: [], ids: new Set() };
  let t = Date.parse("2026-10-10T10:00:00Z");
  return {
    mem,
    projectForRoot: async (root) => [...mem.projects.values()].find((p) => p.rootBuildId === root) ?? null,
    project: async (id) => mem.projects.get(id) ?? null,
    assets: async (pid) => mem.assets.filter((a) => a.projectId === pid),
    assetById: async (id) => mem.assets.find((a) => a.id === id) ?? null,
    revisions: async (pid) => mem.revs.filter((r) => r.projectId === pid),
    async addRevision(pid, input) {
      const p = mem.projects.get(pid)!;
      if (input.expectedHeadId !== undefined && input.expectedHeadId !== p.headRevisionId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const seq = mem.revs.filter((r) => r.projectId === pid).length + 1;
      const r = { id: `rev${mem.revs.length + 1}`, projectId: pid, seq, kind: input.kind, status: input.status ?? "pending", message: input.message ?? null, createdAt: new Date(t += 1000), manifest: input.manifest as RevRow["manifest"], modBuildId: input.modBu
      mem.revs.push(r); p.headRevisionId = r.id;
      return r;
    },
    async recordAsset(pid, a) {
      const hit = mem.assets.find((x) => x.projectId === pid && x.kind === a.kind && x.assetKey === a.assetKey && x.sha256 === a.sha256);
      if (hit) return hit;
      const row: AssetRow = { id: `as${mem.assets.length + 1}`, projectId: pid, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance
      mem.assets.push(row);
      return row;
    },
    async reserve(pid, kind, key) { const b = buildIdentifier(mem.projects.get(pid)!.namespace, kind, key); if (!b.ok) throw new Error(b.error); mem.ids.add(b.id); return { fullId: b.id }; },
  };
}
