// a "vanilla-like" 16x16 stick: outlined diagonal
const STICK = raster(16, (x, y) => (Math.abs(x - (15 - y)) <= 1 && x > 2 && x < 14 ? (Math.abs(x - (15 - y)) === 1 ? [40, 30, 20, 255] : [140, 100, 60, 255]) : [0, 0, 0, 0]));
