describe("policy + delta", () => {
  it("GameBase is validated strictly; retention", () => {
    const b = { legal: "game-derived", source: "byo", sha256: "a".repeat(64), pixelSha256: "b".repeat(64), vanilla: "26.1.2 assets/minecraft/textures/item/stick.png", expiresAt: "2026-10-12T00:00:00Z" };
