    assert.equal(checkGameBase({ ...b, legal: "user-original" }), null);
    assert.equal(checkGameBase({ ...b, extra: 1 }), null);
    assert.ok(baseLive(checkGameBase(b), Date.parse("2026-10-11T00:00:00Z")));
    assert.ok(!baseLive(checkGameBase(b), Date.parse("2026-10-13T00:00:00Z")));
  });
  it("delta-only: unchanged pixels or an expired base never ship; a change ships", () => {
    const base = { legal: "game-derived" as const, source: "dev-foundation" as const, sha256: sha(STICK_PNG), pixelSha256: pixelSha256(STICK), vanilla: null };
    assert.equal(deltaTexture(base, STICK).ship, false);
    const changed = { size: 16, px: new Uint8ClampedArray(STICK.px) }; changed.px[(8 * 16 + 7) * 4] = 255;
    assert.equal(deltaTexture(base, changed).ship, true);
    assert.equal(deltaTexture({ ...base, expiresAt: "2020-01-01T00:00:00Z" }, changed).ship, false);
    assert.equal(deltaFile(base.sha256, base).ship, false);
    assert.equal(deltaFile("c".repeat(64), base, (s) => s === "c".repeat(64)).ship, false);
    assert.equal(deltaFile("d".repeat(64), base, () => false).ship, true);
  });
  it("buildPack leaves an unchanged game-derived texture OUT and ships a changed one", () => {
    const d = docFromRaster("stick_base", STICK); assert.ok(d.ok);
    const base = { legal: "game-derived" as const, source: "dev-foundation" as const, sha256: sha(STICK_PNG), pixelSha256: pixelSha256(renderDoc(d.doc)), vanilla: null };
    const same: TextureDoc = { ...d.doc, base };
    const edited: TextureDoc = { ...d.doc, name: "stick_red", base, paint: { ...d.doc.paint!, colors: [...d.doc.paint!.colors, "#ff0000"], set: d.doc.paint!.set.map((v, i) => (i % 2 === 1 && i === 1 ? d.doc.paint!.colors.length : v)) } };
    assert.ok(checkDoc(edited).ok);
