// Cyrus R42 game-derived assets: vanilla reference catalog rows, the dev foundation store (fail closed), bring-your-own
// vanilla files (hash-verified, job retention) and delta-only export. Everything synthetic: no Mojang file is read.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { encodePng } from "../lib/cyrus/textures/png";
import type { Raster } from "../lib/cyrus/textures/render";
