import { validateModSpec } from "../lib/cyrus/engine-core/spec";

const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
function raster(size: number, f: (x: number, y: number) => [number, number, number, number]): Raster {
  const px = new Uint8ClampedArray(size * size * 4);
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) px.set(f(x, y), (y * size + x) * 4);
  return { size, px };
}
// a "vanilla-like" 16x16 stick: outlined diagonal
const STICK = raster(16, (x, y) => (Math.abs(x - (15 - y)) <= 1 && x > 2 && x < 14 ? (Math.abs(x - (15 - y)) === 1 ? [40, 30, 20, 255] : [140, 100, 60, 255]) : [0, 0, 0, 0]));
const STICK_PNG = encodePng(STICK);

describe("policy + delta", () => {
  it("GameBase is validated strictly; retention", () => {
    const b = { legal: "game-derived", source: "byo", sha256: "a".repeat(64), pixelSha256: "b".repeat(64), vanilla: "26.1.2 assets/minecraft/textures/item/stick.png", expiresAt: "2026-10-12T00:00:00Z" };
    assert.ok(checkGameBase(b));
    assert.equal(checkGameBase({ ...b, legal: "user-original" }), null);
    assert.equal(checkGameBase({ ...b, extra: 1 }), null);
    assert.ok(baseLive(checkGameBase(b), Date.parse("2026-10-11T00:00:00Z")));
    assert.ok(!baseLive(checkGameBase(b), Date.parse("2026-10-13T00:00:00Z")));
  });
  it("delta-only: unchanged pixels or an expired base never ship; a change ships", () => {
    const base = { legal: "game-derived" as const, source: "dev-foundation" as const, sha256: sha(STICK_PNG), pixelSha256: pixelSha256(STICK), vanilla: null };
    assert.equal(deltaTexture(base, STICK).ship, false);
    const changed = { size: 16, px: new Uint8ClampedArray(STICK.px) }; changed.px[(8 * 16 + 7) * 4] = 255;
    assert.equal(deltaTexture(base, changed).ship, true);
    assert.equal(deltaTexture({ ...base, expiresAt: "2020-01-01T00:00:00Z" }, changed).ship, false);
    assert.equal(deltaFile(base.sha256, base).ship, false);
    assert.equal(deltaFile("c".repeat(64), base, (s) => s === "c".repeat(64)).ship, false);
    assert.equal(deltaFile("d".repeat(64), base, () => false).ship, true);
  });
  it("buildPack leaves an unchanged game-derived texture OUT and ships a changed one", () => {
    const d = docFromRaster("stick_base", STICK); assert.ok(d.ok);
    const base = { legal: "game-derived" as const, source: "dev-foundation" as const, sha256: sha(STICK_PNG), pixelSha256: pixelSha256(renderDoc(d.doc)), vanilla: null };
    const same: TextureDoc = { ...d.doc, base };
    const edited: TextureDoc = { ...d.doc, name: "stick_red", base, paint: { ...d.doc.paint!, colors: [...d.doc.paint!.colors, "#ff0000"], set: d.doc.paint!.set.map((v, i) => (i % 2 === 1 && i === 1 ? d.doc.paint!.colors.length : v)) } };
    assert.ok(checkDoc(edited).ok);
    const r = buildPack({ namespace: "nx_test", description: "t", mcVersion: "1.21.11", textures: [same, edited] });
    assert.ok(r.ok, !r.ok ? r.error : "");
    assert.deepEqual(r.pack.leftOut?.map((x) => x.name), ["stick_base"]);
    assert.ok(r.pack.files.includes("assets/nx_test/textures/item/stick_red.png"));
    assert.ok(!r.pack.files.some((f) => f.includes("stick_base")));
  });
  it("normalises game PNGs: first animation frame, icons halved, soft alpha made binary", () => {
    const strip = encodePng({ size: 16, px: new Uint8ClampedArray(16 * 16 * 4).fill(200) }); // square: unchanged
    const n = normaliseGamePng(strip); assert.ok(!("error" in n)); assert.equal(n.raster.size, 16);
  });
});

// ------------------------------------------------------------------------------------------------ dev foundation
function foundationFixture(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-found-"));
  const s = sha(STICK_PNG);
  fs.mkdirSync(path.join(dir, "files", s.slice(0, 2)), { recursive: true });
  fs.writeFileSync(path.join(dir, "files", s.slice(0, 2), s), STICK_PNG);
  const ogg = Buffer.from("OggS-fake"), so = sha(ogg);
  fs.mkdirSync(path.join(dir, "files", so.slice(0, 2)), { recursive: true });
  fs.writeFileSync(path.join(dir, "files", so.slice(0, 2), so), ogg);
  fs.writeFileSync(path.join(dir, "index.json"), JSON.stringify({ schema: 1, sets: [{ id: "vanilla-26.1.2", label: "V", provenance: "mojang-vanilla", version: "26.1.2", verified: true, entries: 2 }, { id: "mc-items-unknown", label: "U", provenance: "unknown", version: null, verified: false, entries: 0 }],
    entries: [{ sha256: s, set: "vanilla-26.1.2", path: "assets/minecraft/textures/item/stick.png", kind: "texture", name: "stick", bytes: STICK_PNG.length, tags: ["item", "stick"], w: 16, h: 16, vanilla: { version: "26.1.2", path: "assets/minecraft/textures/item/stick.png" } },
      { sha256: so, set: "vanilla-26.1.2", path: "assets/minecraft/sounds/mob/zombie/hurt1.ogg", kind: "sound", name: "mob/zombie/hurt1", bytes: ogg.length, tags: ["mob", "zombie", "hurt1"] }] }));
  return dir;
}
const DEV = (dir: string) => ({ CYRUS_DEV_FOUNDATION: "1", CYRUS_DEV_FOUNDATION_DIR: dir, NODE_ENV: "development" });

describe("dev foundation store: fail closed", () => {
  it("refuses without the flag, in production, without a dir, inside a production tree", () => {
    const dir = foundationFixture();
    assert.equal(foundationGate({ CYRUS_DEV_FOUNDATION_DIR: dir }).ok, false);
    assert.match((foundationGate({ ...DEV(dir), NODE_ENV: "production" }) as { reason: string }).reason, /never runs in production/);
    assert.equal(foundationGate({ CYRUS_DEV_FOUNDATION: "1" }).ok, false);
    assert.equal(foundationGate({ ...DEV("/opt/nxeon") }).ok, false);
    assert.equal(foundationGate({ ...DEV(path.join(dir, "nope")) }).ok, false);
    _resetFoundationCache();
    assert.equal(loadFoundation({ ...DEV(dir), NODE_ENV: "production" }), null);
    assert.ok(loadFoundation(DEV(dir)));
  });
  it("search, hash-verified reads (a tampered file is refused), slot resolution", () => {
    const dir = foundationFixture(); _resetFoundationCache();
    const f = loadFoundation(DEV(dir))!;
    assert.equal(searchFoundation(f, "stick").items[0].name, "stick");
    const s = sha(STICK_PNG);
    assert.deepEqual(readFoundationFile(f, s), STICK_PNG);
    assert.equal(resolveFoundationSlot({ id: "x", kind: "texture", source: "imported", foundationRef: `vf:${s}` }, f).ok, true);
    assert.equal(resolveFoundationSlot({ id: "x", kind: "sound", source: "imported", foundationRef: `vf:${s}` }, f).ok, false);
    assert.equal(resolveFoundationSlot({ id: "x", kind: "texture", source: "imported", foundationRef: `vf:${s}` }, null).ok, false);
    fs.writeFileSync(path.join(dir, "files", s.slice(0, 2), s), Buffer.from("tampered"));
    assert.equal(readFoundationFile(f, s), null);
  });
});

// ------------------------------------------------------------------------------------------------ studio flows
const NS = namespaceFor("u1", "BansheeHunt");
const PID = "cp" + "2".repeat(20);
function memStore(): StudioStore & { assets_: AssetRow[] } {
  const projects = new Map<string, ProjectRow>([[PID, { id: PID, userId: "u1", namespace: NS, rootBuildId: "mb1", headRevisionId: null, title: null }]]);
  const revs: (RevRow & { projectId: string })[] = []; const assets: AssetRow[] = [];
  let t = Date.parse("2026-10-11T10:00:00Z");
  return {
    assets_: assets,
    projectForRoot: async (root) => [...projects.values()].find((p) => p.rootBuildId === root) ?? null,
    project: async (id) => projects.get(id) ?? null,
    assets: async (pid) => assets.filter((a) => a.projectId === pid),
    assetById: async (id) => assets.find((a) => a.id === id) ?? null,
    revisions: async (pid) => revs.filter((r) => r.projectId === pid),
    async addRevision(pid, input) {
      const p = projects.get(pid)!;
      if (input.expectedHeadId !== undefined && input.expectedHeadId !== p.headRevisionId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const r = { id: `rev${revs.length + 1}`, projectId: pid, seq: revs.length + 1, kind: input.kind, status: input.status ?? "pending", message: input.message ?? null, createdAt: new Date(t += 1000), manifest: input.manifest as RevRow["manifest"], modBuildId: input.modBuildId ?? null } as RevRow & { projectId: string };
      revs.push(r); p.headRevisionId = r.id; return r;
    },
    async recordAsset(pid, a) {
      const row: AssetRow = { id: `as${assets.length + 1}`, projectId: pid, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t) };
      assets.push(row); return row;
    },
    async reserve(pid, kind, key) { const b = buildIdentifier(projects.get(pid)!.namespace, kind, key); if (!b.ok) throw new Error(b.error); return { fullId: b.id }; },
  };
}
function apiFor(o: { preview?: boolean; env?: Record<string, string>; refDir?: string | null; foundDir?: string | null }) {
  const store = memStore(); const contributed: unknown[] = []; const published: Buffer[] = [];
  const service: StudioServiceDeps = {
    store, planOf: async () => "all", deliveryOn: () => false, contribute: (c) => { contributed.push(c); },
    chain: async (_u, r) => (r === "mb1" ? { rootBuildId: "mb1", latestBuildId: "mb1", mcVersion: "1.21.11", pluginName: "BansheeHunt", assets: null, candidateBuilds: [] } : null),
    publish: async (zip) => { published.push(zip); return { ok: true, url: "https://p/x.zip", sha1: "s" }; },
  };
  const deps = { viewer: async () => ({ userId: "u1", preview: o.preview ?? true }), service, candidates: { id: "fake" }, catalog: { providers: [], planOf: async () => "all" }, rateLimit: () => ({ ok: true }), uploads: null } as unknown as StudioApiDeps;
  const env = { ...(o.env ?? {}), ...(o.refDir ? { [VANILLA_REFERENCE_ENV]: o.refDir } : {}), ...(o.foundDir ? DEV(o.foundDir) : {}) };
  _resetVanillaReferenceCache(); _resetFoundationCache();
  const g: G.GameAssetDeps = { env, reference: () => loadVanillaReference(env), foundation: () => loadFoundation(env) };
  return { store, deps, g, contributed, published };
}
const U = "http://localhost/api/cyrus/assets/v1/game-assets";
const post = (p: string, body: unknown) => new Request(U + p, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
function refFixture(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-ref-"));
  fs.mkdirSync(path.join(dir, "26.1.2"));
  fs.writeFileSync(path.join(dir, "26.1.2", "files.json"), JSON.stringify({ files: { "assets/minecraft/textures/item/stick.png": [sha(STICK_PNG), STICK_PNG.length] } }));
  return dir;
}

describe("bring your own vanilla files (BYO)", () => {
  it("off = 404; on without the private reference = 503 (fail closed)", async () => {
    const a = apiFor({});
    assert.equal((await G.handleByoVerify(post("/verify", { files: [{ path: "x", sha256: "a".repeat(64) }] }), a.deps, a.g)).status, 404);
    const b = apiFor({ env: { CYRUS_BYO_GAME_ASSETS: "1" } });
    assert.equal((await G.handleByoVerify(post("/verify", { files: [{ path: "x", sha256: "a".repeat(64) }] }), b.deps, b.g)).status, 503);
    assert.equal((await G.handleByoImport(post("/import", { projectId: PID, key: "stick_x", dataBase64: STICK_PNG.toString("base64") }), b.deps, b.g)).status, 503);
  });
  it("verifies by hash, imports only an unchanged vanilla texture, keeps it game-derived (job retention), never contributes, ships delta-only", async () => {
    const a = apiFor({ env: { CYRUS_BYO_GAME_ASSETS: "1" }, refDir: refFixture() });
    const v = await (await G.handleByoVerify(post("/verify", { files: [{ path: "x/stick.png", sha256: sha(STICK_PNG) }, { path: "mine.png", sha256: "e".repeat(64) }] }), a.deps, a.g)).json() as { files: { ok: boolean; vanilla: string | null }[] };
    assert.deepEqual(v.files.map((f) => [f.ok, f.vanilla]), [[true, "26.1.2 assets/minecraft/textures/item/stick.png"], [false, null]]);
    const other = encodePng(raster(16, () => [9, 9, 9, 255]));
    assert.equal((await G.handleByoImport(post("/import", { projectId: PID, key: "stick_x", dataBase64: other.toString("base64") }), a.deps, a.g)).status, 422);
    const r = await G.handleByoImport(post("/import", { projectId: PID, key: "stick_x", dataBase64: STICK_PNG.toString("base64"), expectedHeadId: null }), a.deps, a.g);
    assert.equal(r.status, 200, await r.clone().text());
    const body = await r.json() as { pack: { leftOut?: { name: string }[] }; base: { expiresAt?: string; source: string } };
    assert.equal(body.base.source, "byo"); assert.ok(body.base.expiresAt);
    assert.deepEqual(body.pack.leftOut?.map((x) => x.name), ["stick_x"], "unchanged vanilla texture is not packed");
    const row = a.store.assets_.at(-1)!;
    const prov = row.provenance as Record<string, unknown>;
    assert.equal(row.origin, "imported"); assert.equal(prov.legalClass, "game-derived"); assert.equal(prov.retention, "job"); assert.equal(prov.libraryEligible, false);
    assert.equal(a.contributed.length, 0);
    // an edit: the client strips `base`; the server carries it from the base row and the changed texture ships
    const doc = { ...(prov.doc as TextureDoc) }; delete (doc as { base?: unknown }).base;
    doc.paint = { ...doc.paint!, colors: [...doc.paint!.colors, "#00ff00"], set: doc.paint!.set.map((x, i) => (i === 1 ? doc.paint!.colors.length : x)) };
    const s2 = await saveTexture(a.deps.service, { userId: "u1", projectId: PID, key: "stick_x", doc, baseAssetId: row.id, expectedHeadId: (await a.store.project(PID))!.headRevisionId });
    const row2 = a.store.assets_.at(-1)!;
    assert.equal(((row2.provenance as { doc: TextureDoc }).doc.base)?.source, "byo");
    assert.ok("sha1" in s2.pack && !s2.pack.leftOut);
    assert.equal(a.contributed.length, 0, "an edit of game-derived content is never contributed");
  });
});

describe("dev foundation in the studios (owner only)", () => {
  it("non-preview viewers and a closed gate get 404; preview lists, serves and uses", async () => {
    const dir = foundationFixture();
    const np = apiFor({ preview: false, foundDir: dir });
    assert.equal((await G.handleFoundationList(new Request(U + "/foundation?q=stick"), np.deps, np.g)).status, 404);
    const prod = apiFor({ foundDir: dir, env: { NODE_ENV: "production" } });
