    const a = apiFor({ foundDir: dir });
    const l = await (await G.handleFoundationList(new Request(U + "/foundation?q=stick"), a.deps, a.g)).json() as { items: { sha256: string; status: string; libraryEligible: boolean }[] };
    assert.equal(l.items[0].status, "dev-foundation"); assert.equal(l.items[0].libraryEligible, false);
    const file = await G.handleFoundationFile(new Request(U), a.deps, a.g, l.items[0].sha256);
