  });
});

// ------------------------------------------------------------------------------------------------ catalog tools
describe("catalog tools: vanilla reference rows + dev foundation rows", () => {
  const index = createMemoryCatalogIndex([]);
  it("vanilla reference entries are metadata only and never library slots", async () => {
    assert.ok(vanillaRefEntries().length > 4000);
