    if (v.getUint32(p, true) !== 0x02014b50) break;
    const method = v.getUint16(p + 10, true), csize = v.getUint32(p + 20, true), nlen = v.getUint16(p + 28, true), xlen = v.getUint16(p + 30, true), clen = v.getUint16(p + 32, true), lho = v.getUint32(p + 42, true);
    const name = dec.decode(u8.subarray(p + 46, p + 46 + nlen));
    p += 46 + nlen + xlen + clen;
    if (!want(name) || out.length >= max) continue;
    const lnl = v.getUint16(lho + 26, true), lxl = v.getUint16(lho + 28, true);
    const raw = u8.subarray(lho + 30 + lnl + lxl, lho + 30 + lnl + lxl + csize);
    if (method === 0) out.push({ name, data: raw.slice() });
    else if (method === 8) out.push({ name, data: await inflateRaw(raw) });
  }
  return out;
}

/**
 * Everything usable in what the user picked: a game jar or zip (textures + models), an install's `assets` folder
 * (indexes/*.json + objects/: the sounds), or loose .png/.ogg/.json files (path from the folder they were in).
 */
export async function collectGameFiles(files: File[], onProgress?: (n: number) => void): Promise<GameFile[]> {
  const out: GameFile[] = [];
  const push = (path: string, data: Uint8Array) => { if (WANT.test(path) && out.length < MAX_FILES) out.push({ path, name: path.split("/").pop()!, kind: kindOf(path), data }); };
  const rel = (f: File) => ((f as File & { webkitRelativePath?: string }).webkitRelativePath || f.name).replace(/\\/g, "/");
  // an install folder: the asset index maps "minecraft/sounds/..." to objects/<aa>/<sha1>
  const index = files.find((f) => /(^|\/)indexes\/[^/]+\.json$/.test(rel(f)));
  if (index) {
    const objs = new Map(files.filter((f) => /\/objects\/[0-9a-f]{2}\/[0-9a-f]{40}$/.test(rel(f))).map((f) => [rel(f).split("/").pop()!, f]));
    const ix = JSON.parse(await index.text()) as { objects?: Record<string, { hash: string }> };
    for (const [name, o] of Object.entries(ix.objects ?? {})) {
      const path = `assets/${name}`;
      if (!WANT.test(path) || !objs.has(o.hash)) continue;
      push(path, new Uint8Array(await objs.get(o.hash)!.arrayBuffer()));
      if (out.length % 200 === 0) onProgress?.(out.length);
    }
  }
  for (const f of files) {
    const r = rel(f);
    if (/\.(jar|zip)$/i.test(f.name)) {
      for (const e of await readZip(await f.arrayBuffer(), (n) => WANT.test(n))) push(e.name, e.data);
      onProgress?.(out.length);
      continue;
    }
    const m = r.match(/assets\/minecraft\/(textures|sounds|models)\/.+$/);
    if (m) push(m[0], new Uint8Array(await f.arrayBuffer()));
    else if (/\.(png|ogg)$/i.test(f.name)) push(`assets/minecraft/${f.name.endsWith(".ogg") ? "sounds" : "textures/item"}/${f.name}`, new Uint8Array(await f.arrayBuffer()));
  }
  for (let i = 0; i < out.length; i++) { out[i].sha256 = await sha256Hex(out[i].data); if (i % 300 === 0) onProgress?.(i); }
  return out;
}

export const toBase64 = (d: Uint8Array) => { let s = ""; for (let i = 0; i < d.length; i += 0x8000) s += String.fromCharCode(...d.subarray(i, i + 0x8000)); return btoa(s); };

