"use client";
// R42 "Minecraft files" panel of the Texture and Sound studios: (1) BRING YOUR OWN: read textures / sounds / models
// from the user's own Minecraft jar or install IN THE BROWSER, hash them, let the server verify them against the
// private vanilla reference, and start a retexture from one; (2) DEV FOUNDATION (owner, dev host only): the owner's
// vanilla reference copy, "Use as foundation". Both are game-derived: never library, never shared, delta-only export.
// Every rule is enforced server side (lib/cyrus/gameassets/http.ts); this panel only shows what the server allows.
import { useEffect, useMemo, useRef, useState } from "react";
import { ApiError, studioApi, type FoundationItem, type GameCaps, type VerifiedFile } from "./api";
import { collectGameFiles, toBase64, type GameFile } from "./game-files";
import { SI } from "./icons";
import { useToast } from "./StudioShell";

const keyFrom = (s: string) => { const k = s.toLowerCase().replace(/\.(png|ogg|json)$/, "").replace(/[^a-z0-9_]+/g, "_").replace(/^[^a-z]+/, "").slice(0, 32); return k.length >= 2 ? k : "custom_texture"; };

export function GameAssetsPanel({ kind, projectId, headRevisionId, onAdded }: { kind: "texture" | "sound"; projectId: string; headRevisionId: string | null; onAdded: (key: string) => Promise<void> }) {
  const [caps, setCaps] = useState<GameCaps | null>(null);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => { studioApi.gameCaps().then(setCaps).catch((e) => setErr((e as Error).message)); }, []);
  if (err) return <div className="cys-empty">{err}</div>;
  if (!caps) return <div className="cys-empty">Loading…</div>;
  return (
    <div className="lib ga" data-testid="game-assets">
      <Byo kind={kind} caps={caps} projectId={projectId} headRevisionId={headRevisionId} onAdded={onAdded} />
      {caps.foundation.on && <Foundation kind={kind} caps={caps} projectId={projectId} headRevisionId={headRevisionId} onAdded={onAdded} />}
    </div>
  );
}

type P = { kind: "texture" | "sound"; caps: GameCaps; projectId: string; headRevisionId: string | null; onAdded: (key: string) => Promise<void> };

function Byo({ kind, caps, projectId, headRevisionId, onAdded }: P) {
  const toast = useToast();
  const pick = useRef<HTMLInputElement>(null), dir = useRef<HTMLInputElement>(null);
  const [files, setFiles] = useState<(GameFile & { v?: VerifiedFile })[]>([]);
  const [busy, setBusy] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [sel, setSel] = useState<string | null>(null);
  const [key, setKey] = useState("");
  const [audio, setAudio] = useState<string | null>(null);
  const on = caps.byo.on;

  const read = async (list: FileList | null) => {
    if (!list?.length) return;
    try {
      setBusy("Reading your files on this device…");
      const got = await collectGameFiles([...list], (n) => setBusy(`Reading your files on this device… ${n}`));
      if (!got.length) { toast("No Minecraft textures, sounds or models found there. Pick the game jar (versions/<version>/<version>.jar) or the .minecraft/assets folder.", true); return; }
      setBusy(`Checking ${got.length} files with Nxeon (hashes only)…`);
      const verified: VerifiedFile[] = [];
      for (let i = 0; i < got.length; i += 500) verified.push(...(await studioApi.byoVerify(got.slice(i, i + 500).map((f) => ({ path: f.path, sha256: f.sha256! })))).files);
      const bySha = new Map(verified.map((v) => [v.sha256, v]));
      setFiles(got.map((f) => ({ ...f, v: bySha.get(f.sha256!) })));
      toast(`${verified.filter((v) => v.ok).length} of ${got.length} files are unchanged vanilla Minecraft files.`);
    } catch (e) { toast(e instanceof ApiError ? e.message : (e as Error).message || "Couldn't read those files.", true); }
    finally { setBusy(null); }
  };
  const shown = useMemo(() => files.filter((f) => f.v?.ok && f.kind === kind && (!q || f.path.includes(q.toLowerCase()))).slice(0, 80), [files, kind, q]);
  const cur = shown.find((f) => f.sha256 === sel) ?? null;
  useEffect(() => { if (cur) setKey(keyFrom(cur.name)); }, [cur]);
  useEffect(() => () => { if (audio) URL.revokeObjectURL(audio); }, [audio]);
  const thumb = (f: GameFile) => URL.createObjectURL(new Blob([f.data as BlobPart], { type: "image/png" }));

  const use = async () => {
    if (!cur) return;
    setBusy("Starting your texture…");
    try {
      const r = await studioApi.byoImport({ projectId, key, dataBase64: toBase64(cur.data), expectedHeadId: headRevisionId });
      toast(`Started ${key} from ${r.base.vanilla?.split("/").pop() ?? "your file"}. It is yours to retexture; only your changes ship.${r.notes.length ? ` (${r.notes.join("; ")})` : ""}`);
      setSel(null); await onAdded(key);
    } catch (e) { toast(e instanceof ApiError ? e.message : "Couldn't import it. Nothing was changed.", true); }
    finally { setBusy(null); }
  };

  return (
    <section className="ga-sec" aria-label="Your Minecraft files">
      <div className="cys-ph"><span className="cys-eyebrow">Your Minecraft files</span><span className="cys-tag dim">game-derived</span></div>
      <ul className="ga-notice">{caps.byo.notice.map((l) => <li key={l}>{l}</li>)}</ul>
      {!on && <div className="lib-lock"><SI n="lock" /><span>{caps.byo.reason === "off" ? "Bringing your own Minecraft files is not switched on yet." : caps.byo.reason ?? "Not available."}</span></div>}
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
        <button type="button" className="cys-btn sm" disabled={!on || !!busy} onClick={() => pick.current?.click()} data-testid="byo-pick"><SI n="upload" />Game jar or files</button>
        <button type="button" className="cys-btn sm ghost" disabled={!on || !!busy} onClick={() => dir.current?.click()} title="Pick your .minecraft/assets folder (sounds live there, not in the jar)"><SI n="package" />Install folder</button>
        <input ref={pick} type="file" multiple accept=".jar,.zip,.png,.ogg,.json" hidden onChange={(e) => { void read(e.target.files); e.target.value = ""; }} />
        <input ref={dir} type="file" multiple hidden {...({ webkitdirectory: "", directory: "" } as Record<string, string>)} onChange={(e) => { void read(e.target.files); e.target.value = ""; }} />
      </div>
      {busy && <div className="cys-hint" role="status">{busy}</div>}
      {files.length > 0 && (
        <>
          <div className="lib-srch"><SI n="search" /><input className="cys-field" value={q} onChange={(e) => setQ(e.target.value)} placeholder={kind === "texture" ? "Filter: sword, ore, stick…" : "Filter: zombie, door…"} aria-label="Filter your files" /></div>
          {cur && (
            <div className="lib-detail">
              <div className="pv">{kind === "texture" ? /* eslint-disable-next-line @next/next/no-img-element */ <img src={thumb(cur)} alt="" style={{ imageRendering: "pixelated" }} /> : <SI n="wave" />}</div>
              <div className="meta">
                <b>{cur.name}</b>
                <span className="cys-hint">Vanilla {cur.v?.vanilla} · verified unchanged</span>
                {kind === "texture" ? (
                  <>
                    <label className="cys-hint" htmlFor="ga-key">Name in this mod</label>
                    <div style={{ display: "flex", gap: 6 }}>
                      <input id="ga-key" className="cys-field" value={key} onChange={(e) => setKey(e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, "").slice(0, 32))} />
                      <button type="button" className="cys-btn sm primary" disabled={!!busy || key.length < 2} onClick={() => void use()} data-testid="byo-use"><SI n="edit" />Retexture this</button>
                    </div>
                    <span className="cys-hint">Kept in this project for 7 days. Export ships only your changed texture.</span>
                  </>
                ) : (
                  <>
                    <button type="button" className="cys-btn xs" onClick={() => { if (audio) URL.revokeObjectURL(audio); const u = URL.createObjectURL(new Blob([cur.data as BlobPart], { type: "audio/ogg" })); setAudio(u); void new Audio(u).play(); }}><SI n="play" />Play (from your device)</button>
                    {(cur.v?.events ?? []).map((e) => <span key={e.event} className="cys-hint">Plays as <b>{e.event}</b>: {e.how}</span>)}
                    <span className="cys-hint">To resound it, make your own sound in a sound set and point it at this event; the vanilla file itself never ships.</span>
                  </>
                )}
              </div>
