        <div className="lib-srch" style={{ flex: 1 }}><SI n="search" /><input className="cys-field" value={q} onChange={(e) => setQ(e.target.value)} placeholder={kind === "texture" ? "Search vanilla: diamond sword, stick, ore…" : "Search vanilla sounds: zombie, door…"} aria-label="Search the dev foundation" /></div>
        <select className="cys-field" value={set} onChange={(e) => setSet(e.target.value)} aria-label="Set" style={{ maxWidth: 150 }}>
