import { dirname } from "node:path";
import { loadFoundation, foundationTools, resolveFoundationSlot } from "../lib/cyrus/gameassets/foundation.server";
import { normaliseGamePng } from "../lib/cyrus/gameassets/service";
import { pixelSha256 } from "../lib/cyrus/gameassets/delta";
import { docFromRaster, renderDoc, paintFromBuffers, type TextureDoc } from "../lib/cyrus/studios/paint";
import { buildPack } from "../lib/cyrus/textures/pack";
import { encodePng } from "../lib/cyrus/textures/png";
import { catalogGet, catalogSearch, type ToolContext } from "../lib/cyrus/library/v2/tools";
import { createMemoryCatalogIndex } from "../lib/cyrus/library/v2/retrieval";
import { validateModSpec } from "../lib/cyrus/engine-core/spec";
import { getAdapter } from "../lib/cyrus/adapters";
import { vanillaSummary } from "../lib/cyrus/versions/vanilla/pack-check";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { flyOne, type GateDeps } from "../lib/cyrus/testflight/gate-worker";
import { flightLines, type StoredFlight } from "../lib/cyrus/testflight/gate";

const FX = "/tank/nxeon-build/tmp/testflight/inbox/fx";
const V = "26.1.2";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
