};

/** the deterministic stand-in for a Cyrus texture edit: browns -> ember oranges, the tip glows */
function emberEdit(doc: TextureDoc): TextureDoc {
  const r = renderDoc(doc), n = r.size, px = new Uint8ClampedArray(r.px);
  let top = -1;
  for (let i = 0; i < n * n; i++) {
    if (px[i * 4 + 3] === 0) continue;
    if (top < 0) top = i;
    const [R, G, B] = [px[i * 4], px[i * 4 + 1], px[i * 4 + 2]], l = (R + G + B) / 3;
    px[i * 4] = Math.min(255, 90 + l * 1.1); px[i * 4 + 1] = Math.min(255, 30 + l * 0.55); px[i * 4 + 2] = Math.min(255, 10 + l * 0.15);
  }
  if (top >= 0) { px[top * 4] = 255; px[top * 4 + 1] = 236; px[top * 4 + 2] = 140; }
  const cut = new Uint8Array(n * n);
  return { ...doc, name: "ember_wand", paint: paintFromBuffers(doc.size, px, cut) };
