async function main() {
  const steps: Record<string, unknown> = {};
  const f = loadFoundation();
  if (!f) throw new Error("dev foundation store is off (CYRUS_DEV_FOUNDATION=1 + CYRUS_DEV_FOUNDATION_DIR, not production)");
  const ctx: ToolContext = { index: createMemoryCatalogIndex([]), plan: "all", game: "minecraft", proprietaryCleared: false, vanillaReference: true, foundation: foundationTools(f) };
  // 1. what the model sees
  const search = JSON.parse((await catalogSearch({ query: "magic wand stick" }, ctx)).content) as { vanilla?: { id: string }[]; foundation?: { id: string; t: string; set: string }[] };
  const pick = search.foundation?.find((r) => r.set === "vanilla-26.1.2" && r.t === "stick") ?? search.foundation?.[0];
  if (!pick) throw new Error("no foundation row for the query");
  const detail = JSON.parse((await catalogGet({ id: pick.id }, ctx)).content);
  steps.catalog = { query: "magic wand stick", vanillaRows: search.vanilla, foundationRows: search.foundation, picked: pick.id, detail };
  // 2. the hand-written ModSpec (what the model would write)
  const spec = {
    schemaVersion: 1, game: "minecraft", target: { version: V }, namespace: "nx_f0undat1", summary: "An ember wand retextured from the vanilla stick", routes: ["plugin"],
    requirements: [{ id: "REQ-1", text: "Players can get an ember wand with its own look" }], tests: [{ id: "T-1", kind: "boot", description: "The plugin boots", covers: ["REQ-1"] }],
    install: { side: "server", restartRequired: true },
    assets: [{ id: "ember_wand", kind: "texture", purpose: "the ember wand, retextured from the vanilla stick", source: "imported", foundationRef: pick.id, requirementIds: ["REQ-1"] }],
  };
  const vs = validateModSpec(spec, { adapterFor: getAdapter });
  steps.modspec = vs.ok ? { ok: true, warnings: vs.warnings } : { ok: false, errors: vs.errors };
  if (!vs.ok) throw new Error("ModSpec invalid");
