  if (!slot.ok) throw new Error(slot.reason);
  const norm = normaliseGamePng(slot.bytes);
  if ("error" in norm) throw new Error(norm.error);
  const d = docFromRaster("stick_base", norm.raster);
  if (!d.ok) throw new Error(d.error);
  const base = { legal: "game-derived" as const, source: "dev-foundation" as const, sha256: slot.entry.sha256, pixelSha256: pixelSha256(renderDoc(d.doc)), vanilla: slot.entry.vanilla ? `${slot.entry.vanilla.version} ${slot.entry.vanilla.path}` : null, set: slot.entry.set };
  const unchanged: TextureDoc = { ...d.doc, base };
  const edited: TextureDoc = { ...emberEdit(d.doc), base };
  // 4. the pack
  const built = buildPack({ namespace: spec.namespace, description: "Ember wand (dev foundation demo)", mcVersion: V, textures: [unchanged, edited], allowPreview: true });
  if (!built.ok) throw new Error(built.error);
  steps.pack = { sha1: built.pack.sha1, bytes: built.pack.bytes, format: built.pack.packFormat, files: built.pack.files, leftOut: built.pack.leftOut ?? [] };
  const out = process.argv.includes("--out") ? process.argv[process.argv.indexOf("--out") + 1] : null;
  if (out) { mkdirSync(dirname(out), { recursive: true }); writeFileSync(out.replace(/\.json$/, "-ember_wand.png"), encodePng(renderDoc(edited))); }
  // 5. vanilla checks + a real flight
  const vanilla = vanillaSummary(V, [built.pack.zip]);
  steps.vanilla = vanilla;
  const jar = `${FX}/TfItemModel-1.0.0.jar`;
  const store = new Map<string, StoredFlight>();
  const deps: GateDeps = {
    env: { CYRUS_TESTFLIGHT_GATE: "1" },
    async candidates() { return []; },
    async artifacts() { return { jarPath: jar, datapacks: [], packLoader: null }; },
    async run(s) {
      for (let i = 0, wait = 15000; i < 12; i++, wait = Math.min(wait * 2, 120000)) {
        const r = await runTestFlight(s, { remote: process.argv.includes("--local") ? localRemote : undefined });
        if (r.report.status !== "busy") return r;
        console.log(`busy, retry in ${wait / 1000}s`); await sleep(wait);
      }
      throw new Error("node-2 stayed busy");
    },
    async store(id, fl) { store.set(id, JSON.parse(JSON.stringify(fl))); },
  };
  const b = { id: "foundation-ember-wand", mcVersion: V, pluginName: "TfItemModel", jarSha256: createHash("sha256").update(readFileSync(jar)).digest("hex"),
    result: { commands: [], safety: { verdict: "pass" }, assets: { vanilla } } };
  const t0 = Date.now();
  const r = await flyOne(b, null, deps, () => new Date());
  const fl = store.get(b.id)!;
  steps.flight = { result: r, wallMs: Date.now() - t0, state: fl.state, verdict: fl.verdict, label: fl.label, checks: fl.checks, notes: fl.notes, vanilla: fl.vanilla, lines: flightLines(fl), engine: fl.engine };
  console.log(`flight: ${fl.state} ${fl.verdict} ${fl.label ?? ""} [${fl.checks.map((x) => `${x.id}=${x.status}`).join(" ")}]`);
  const doc = { what: "Cyrus R42 dev-foundation demo: vanilla stick -> ember wand retexture, delta-only pack, vanilla checks, real Test Flight (Paper 26.1.2)", date: new Date().toISOString(), steps };
  if (out) writeFileSync(out, JSON.stringify(doc, null, 1)); else console.log(JSON.stringify(doc, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

