// Cyrus R42 "Minecraft files" screenshots (run ON node-2 against `devhost dev`; dev foundation + BYO switched on).
//   devhost run -- node scripts/cyrus/foundation-shots.mjs   (env: BASE, TOKENS, OUT, JAR = a test zip of vanilla files)
// Writes <OUT>/foundation-*.png and prints page errors + horizontal overflow per shot.
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots";
const JAR = process.env.JAR ?? ".shots/test-client.jar";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".shots/tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const studio = (who, kind) => `/dashboard/cyrus/${tok[who].buildId}/studio/${kind}`;
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;

async function shot(name, who, url, { view = "desktop", theme = "dark", act, ready = ".cys-tab, .cys-empty" } = {}) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) return;
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => errs.push("goto " + e));
  await page.waitForSelector(ready, { timeout: 180000 }).catch((e) => errs.push("wait " + String(e).slice(0, 80)));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click().catch(() => {}); }
  await page.waitForTimeout(2000);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(1500);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}

const mcTab = async (p) => { await p.getByTestId("tab-minecraft").first().click({ timeout: 20000 }); await p.waitForSelector("[data-testid=game-assets]", { timeout: 20000 }); };
const search = (q) => async (p) => { await mcTab(p); await p.getByLabel("Search the dev foundation").fill(q); await p.waitForTimeout(1500); };
const pickFirst = async (p) => { await p.locator("[data-testid=dev-foundation] [role=listitem]").first().click(); await p.waitForSelector("[data-testid=foundation-detail]"); };
const byo = async (p) => { await mcTab(p); await p.locator("[data-testid=game-assets] input[type=file][accept]").setInputFiles(JAR); await p.waitForSelector("text=/unchanged vanilla Minecraft files/", { timeout: 60000 }).catch(() => {}); await p.waitForTimeout(800); };

await shot("foundation-texture-panel", "all", studio("all", "texture"), { act: search("diamond sword") });
await shot("foundation-texture-detail", "all", studio("all", "texture"), { act: async (p) => { await search("stick")(p); await pickFirst(p); } });
await shot("foundation-texture-used", "all", studio("all", "texture"), { act: async (p) => { await search("stick")(p); await pickFirst(p); await p.locator("#fd-key").fill("ember_wand"); await p.getByTestId("foundation-use").click(); await p.waitForTimeout(4000); } });
await shot("foundation-items-unknown", "all", studio("all", "texture"), { act: async (p) => { await mcTab(p); await p.getByLabel("Set").selectOption("mc-items-unknown"); await p.getByLabel("Search the dev foundation").fill("diamond"); await p.waitForTimeout(1500); await pickFirst(p); } });
await shot("foundation-byo-verified", "all", studio("all", "texture"), { act: async (p) => { await byo(p); await p.getByLabel("Filter your files").fill("sword"); await p.waitForTimeout(600); await p.locator("[aria-label='Your Minecraft files'] [role=listitem]").first().click(); } });
await shot("foundation-sound-panel", "all", studio("all", "sound"), { act: async (p) => { await mcTab(p); await p.getByLabel("Search the dev foundation").fill("zombie hurt"); await p.waitForTimeout(1500); await pickFirst(p); } });
await shot("foundation-texture-light", "all", studio("all", "texture"), { theme: "light", act: search("golden apple") });
await shot("foundation-outsider-none", "outsider", studio("outsider", "texture"), { ready: "body" });
await browser.close();

