// Cyrus docs coverage (r46): keeps docs/cyrus LIVING. It fails when
//  - a Cyrus env flag / setting / route / DB table / adapter / game / registry version / OpenAPI operation exists in code
//    but is missing from the generated reference pages (docs/cyrus/reference/*),
//  - a generated page is stale (re-run: npx tsx scripts/cyrus/docs-build.ts),
//  - docs/cyrus/_data/features.json names a flag, branch-less doc or anchor that does not exist,
//  - a relative link in docs/cyrus is broken, a numbered page is missing from the README, or the admin viewer is gone,
//  - a secret-looking string or an IP address slipped into the docs.
// The detection here is deliberately a second, simpler implementation than the generator's, so a gap in one is caught by the other.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
